"""Original bilingual engineering exercises; public references are background, not recipes."""
import json,copy,pathlib
ROOT=pathlib.Path(__file__).resolve().parents[2]
CAT={x['id']:x for x in json.load(open(ROOT/'public/academy/data/catalog.json'))}
PLACE={x['courseId']:x for x in json.load(open(ROOT/'public/academy/data/course-places.json'))['courses']}
D={}
def add(n,focus,stages,source,related,example,units,place='packaging'):
 rows=[]
 for row in units.strip().splitlines():
  fields=[x.strip().split('~',1) for x in row.split('|')]
  assert len(fields)==4 and all(len(x)==2 for x in fields),(n,row)
  rows.append(fields)
 assert len(rows)==12,(n,len(rows))
 D[f'a{n}']={'focus':focus.split('~'),'stages':[x.split('~') for x in stages.split('|')],'source':source.split(),'related':related,'example':example.split('~'),'units':rows,'place':place}
add(103,'凸塊共面性、電流密度與界面可靠度~Bump coplanarity, current density and interface reliability','互連幾何與來料~Interconnect geometry and input|圖形與金屬生長~Patterning and metal growth|界面與封裝互動~Interfaces and package interaction|量測與可靠度放行~Metrology and reliability release','atotech asebump', [('a104','共面性與焊料體積決定熱壓接合的接觸分布~Coplanarity and solder volume determine contact distribution during thermocompression','本課形成凸塊，熱壓課研究受力與接合後界面~This course forms bumps; thermocompression studies loading and bonded interfaces'),('a118','兩者皆須連續種子層、圖形電鍍與去種子層~Both require continuous seed, patterned plating and seed removal','凸塊控制高度與頂面，RDL 控制線寬、厚度與跨材料應力~Pillars control height and topography; RDL controls width, thickness and cross-material stress')], '假設銅柱直徑 20 μm、長 40 μm、ρ=1.7×10⁻⁸ Ω·m：R=ρL/A≈2.16 mΩ。10 mA 對應 J≈3.18×10⁷ A/m²；忽略接觸、尺寸效應與溫升，不能據此宣稱安全電流。~For an illustrative 20 μm diameter, 40 μm long Cu pillar with ρ=1.7×10⁻⁸ Ω·m, R=ρL/A≈2.16 mΩ. At 10 mA, J≈3.18×10⁷ A/m². Contact resistance, size effects and heating are omitted, so this does not establish a safe current.', '''
焊墊與凸塊座標~Pad and bump coordinates|焊墊開口、凸塊中心與封裝對位誤差須同一座標系，局部偏心會縮小有效接合面。~Pad openings, pillar centers and assembly overlay need one coordinate system; local eccentricity reduces useful contact area.|疊合設計輪廓與量測中心，分開平移、旋轉與非線性殘差。~Overlay design contours and measured centers; separate translation, rotation and nonlinear residuals.|以全片平均偏移代表每顆凸塊重疊~Using mean wafer offset to represent every bump overlap
種子層連續性~Seed continuity|開路種子層使局部電位與沉積量失控；名義厚度相同不保證跨地形導通。~A discontinuous seed disrupts local potential and deposition; identical nominal thickness does not guarantee continuity over topography.|以片電阻地圖配合截面查看孔邊覆蓋，將探針接觸異常另列。~Combine sheet-resistance maps with cross-sections at aperture edges and isolate probe-contact errors.|僅用中心種子厚度證明全片電鍍連通~Using center seed thickness alone to prove plating continuity
光阻孔洞與側壁~Resist apertures and sidewalls|孔徑、側壁角與光阻厚度共同決定柱的截面與可成長高度；顯影殘留可阻斷底部成核。~Aperture size, sidewall angle and resist thickness jointly constrain pillar shape and height; developer residue can obstruct nucleation.|比較俯視孔徑、底部開口與截面角度，不把頂口尺寸當作柱底尺寸。~Compare top-view diameter, bottom opening and cross-section angle; the top opening is not the base diameter.|頂口尺寸合格即代表柱底無殘留~Assuming a correct top opening proves a residue-free base
電荷與高度預算~Charge and height budget|法拉第關係把總電荷連到理想沉積質量，實際高度還受電流效率、有效面積及邊緣電流影響。~Faraday's relation links charge to ideal deposited mass; actual height also depends on current efficiency, active area and edge current.|固定圖形密度比較電荷與高度斜率，檢查中心至邊緣殘差。~Compare charge–height slopes at fixed pattern density and inspect center-to-edge residuals.|總電荷相同必有相同每顆柱高~Assuming equal total charge gives equal height at every pillar
圖形密度與共面性~Pattern density and coplanarity|高低圖形密度區分配不同局部電流；共面性須以單晶粒接觸面與全片高度分布分別定義。~Dense and sparse patterns redistribute local current; define coplanarity at both die-contact and wafer-distribution scales.|繪製柱高直方圖並依圖形密度分組，報告最大最小差與重複量測。~Plot pillar-height histograms grouped by pattern density, reporting range and repeat measurements.|平均柱高相同就能同時接觸~Assuming equal mean pillar height ensures simultaneous contact
銅微結構~Copper microstructure|晶粒與雜質影響延展、電阻與後續熱循環；室溫電阻正常並不排除脆化界面。~Grains and impurities affect ductility, resistance and thermal cycling; normal room-temperature resistance does not exclude embrittlement.|將電阻、截面與熱處理前後微結構配對，保持樣本位置可追溯。~Pair resistance, cross-section and pre/post-thermal microstructure with traceable sampling positions.|初始電阻低就代表疲勞壽命長~Assuming low initial resistance proves long fatigue life
阻障與焊料帽~Barrier and solder cap|阻障層與焊料帽在接合中參與擴散與反應；只報總凸塊高會掩蓋各層厚度不足。~Barrier and solder cap participate in diffusion and reaction; reporting total bump height hides deficient individual layers.|量測分層截面及帽體積，將金屬間化合物與未反應焊料分開。~Measure layer-resolved cross-sections and cap volume; distinguish intermetallic from remaining solder.|總凸塊高度能代替各層組成檢查~Using total bump height instead of layer-composition checks
去種子層與側蝕~Seed removal and undercut|移除導通背景需避免柱底側蝕；短路消失與機械根部完整是兩個不同驗收條件。~Removing the conductive background must limit base undercut; eliminating shorts and preserving the mechanical root are separate criteria.|配對絕緣測試與柱根截面，在大間距和密集區各取樣。~Pair isolation tests with pillar-root cross-sections in both sparse and dense regions.|絕緣通過即可忽略柱根側蝕~Ignoring base undercut after isolation passes
電阻與電流密度~Resistance and current density|柱身 R=ρL/A 只描述幾何導體；量測電阻還含接觸與引線，局部狹頸的 J 高於平均。~R=ρL/A describes the pillar body only; measured resistance includes contacts and leads, while a neck has higher J than the average.|做四端與兩端比較，將幾何推算值同實測差額列成未知界面項。~Compare four- and two-terminal results and record excess measured resistance as an unresolved interface term.|兩端電阻可直接反推純銅電阻率~Directly inferring pure-Cu resistivity from two-terminal resistance
剪切測試的破壞位置~Shear-test failure locus|剪切力需連同工具高度、加載方向與破面位置解讀；高峰值也可能來自不相關結構受力。~Interpret shear force with tool height, loading direction and fracture locus; a high peak can include unrelated structural loading.|標示破面在柱身、焊料或焊墊，對照相同幾何的樣本而非只比牛頓數。~Locate fracture in pillar, solder or pad, comparing matched geometry rather than force alone.|最高剪切力必定代表最佳接合界面~Assuming the highest shear force identifies the best interface
電遷移與溫升分辨~Separate electromigration and heating|阻值漂移可能由溫度可逆變化或不可逆空洞引起，必須同時保留電流極性與溫度歷程。~Resistance drift can reflect reversible heating or irreversible voiding; preserve current polarity and thermal history.|比較冷卻後阻值恢復與失效端位置，先排除量測接點飄移。~Compare resistance recovery after cooling and failure location, first excluding probe drift.|通電中電阻上升只能是電遷移~Treating every powered resistance rise as electromigration
組裝交接與抽樣~Assembly handoff and sampling|後段需要柱高、偏心、帽體積與污染的聯合分布；單一合格率不能表示多條件共同成功率。~Assembly needs joint distributions of height, eccentricity, cap volume and contamination; one yield does not represent joint success.|交付可追溯晶粒地圖及不確定度，挑選邊緣條件樣本進行接合驗證。~Deliver traceable die maps with uncertainty and include edge-condition samples in bonding validation.|各項各自合格就保證所有凸塊組裝成功~Assuming individual parameter passes guarantee all-bump assembly
''')
add(104,'力—熱—位移耦合與接合後界面~Force–temperature–displacement coupling and bonded interfaces','接觸設計~Contact design|熱機控制~Thermomechanical control|界面形成~Interface formation|可靠度與驗證~Reliability and verification','besitcb besipub', [('a103','柱高與焊料帽是接合接觸分布的輸入~Pillar height and solder caps set the contact distribution','凸塊製造的共面性不等於加熱受壓後共面性~Fabricated coplanarity differs from hot loaded coplanarity'),('a105','皆須控制表面、接觸面積與熱負荷~Both control surfaces, contact area and thermal load','熱壓可含焊料或聚合物，直接銅接合沒有焊料自對位假設~TCB may include solder or polymer; direct Cu bonding cannot assume solder self-alignment')], '教學假設接觸總力 20 N、有效承載面積 4 mm²，平均壓力為 5 MPa；若只有四分之一面積先接觸，局部平均可達 20 MPa。這不是設備力或溫度配方，實際須由變形與接觸分析界定。~An illustrative 20 N on 4 mm² gives a 5 MPa average pressure. If only one quarter initially touches, its average can reach 20 MPa. This is not a tool force or temperature recipe; deformation/contact analysis determines the actual distribution.', '''
接合堆疊剖面~Bond-stack cross-section|上晶粒、接合點、下基板與工具各有剛性和熱膨脹，邊界不能簡化成兩個完全平板。~Die, joints, substrate and tools have distinct stiffness and expansion; the boundary is not simply two rigid planes.|畫受力與熱流兩張圖，標明受約束及自由伸長位置。~Draw separate load and heat-flow diagrams, identifying constrained and free-expansion locations.|工具平行即可消除堆疊的翹曲~Assuming parallel tools eliminate stack warpage
已知良品與面向~Known-good die and orientation|接合後難以接近的節點須在前段建立電性與面向追溯，鏡像坐標錯誤可造成規則性開路。~Nodes inaccessible after bonding need pre-bond electrical and orientation traceability; mirrored coordinates can produce systematic opens.|以非對稱標記驗證旋轉與翻面，對照良品地圖而非僅辨識條碼。~Verify rotation and flipping with asymmetric marks and compare known-good-die maps, not barcodes alone.|晶粒料號相同即可省略翻面座標檢查~Skipping flip-coordinate checks for identical part numbers
接觸壓力分布~Contact-pressure distribution|總力除以名義面積只是平均；少數高凸塊先承載會造成局部過載與其餘接點未接觸。~Force divided by nominal area is only an average; tall bumps can overload while other joints remain open.|將柱高分布與接觸順序連結，檢查高低點的破面與電阻。~Link bump-height distribution to contact order and inspect fracture/resistance at high and low sites.|固定總力可保證各凸塊同壓~Assuming constant total force guarantees equal bump pressure
溫度讀值與界面溫度~Sensor versus interface temperature|工具感測溫度與接合界面有熱阻、熱容量和延遲；相同設定不保證不同堆疊的相同熱歷程。~Tool sensors and bond interfaces differ through thermal resistance, capacity and delay; identical settings need not yield identical histories.|比較見證件的界面溫度與工具曲線，記錄校正位置和誤差。~Compare witness-interface and tool-temperature traces with calibration location and uncertainty.|工具達設定溫度代表所有界面已同步~Assuming a tool setpoint means every interface is synchronized
熱膨脹對位~Thermal overlay|不同 CTE 的晶粒與基板加熱後產生位置依賴偏移；室溫對位不能直接當熱態對位。~CTE mismatch produces position-dependent displacement on heating; room-temperature alignment is not hot alignment.|在中心、邊緣畫位移向量，檢查比例性伸縮與工具漂移是否可分。~Map displacement vectors at center and edge, separating scale change from tool drift.|熱偏移是一個可全片共用的平移量~Treating thermal displacement as one uniform translation
位移回授與壓縮~Displacement feedback and compression|量到的 Z 位移含工具、基板與接點變形，不能全部算成焊料壓縮。~Measured Z motion includes tool, substrate and joint compliance; it is not all solder compression.|以空載與剛性參考比較回授，再同接合後間隙截面交叉驗證。~Use unloaded and rigid references, then cross-check against post-bond gap sections.|Z 回授位移就是每顆焊點壓縮量~Equating Z feedback with each joint's compression
氧化與潤濕證據~Oxide and wetting evidence|未潤濕、污染與接觸不足可呈相似高電阻，需界面化學或形貌證據才能分辨。~Nonwetting, contamination and inadequate contact can all give high resistance; interface chemistry or morphology is needed to distinguish them.|比較接合面、開路位置與良品對照，避免只用一张低倍率截面。~Compare bond faces, open-site maps and good controls rather than one low-magnification section.|高電阻一律表示加熱不足~Attributing every high resistance to insufficient heating
聚合物流動與排氣~Polymer flow and venting|非導電膜或膠的流動、固化與氣體排出競爭，間隙閉合過快可能封住逃逸路徑。~Polymer flow, curing and gas escape compete; fast gap closure can trap escape paths.|將空洞位置同流動前沿和邊緣排氣路徑對照，加入材料批次資訊。~Compare void locations with fronts and edge vent paths while retaining material-lot information.|增加壓力總能消除所有空洞~Assuming greater pressure always removes all voids
界面反應與脆層~Interface reaction and brittle layers|反應層形成有助於接合，但其厚度、形貌與應力集中需共同評估，並非越厚越可靠。~Reaction layers enable bonding, but thickness, morphology and stress concentration must be assessed together; thicker is not automatically more reliable.|把界面層厚度分布、裂紋路徑及電性配對，區分初始與老化後。~Pair layer-thickness distributions, crack paths and electrical data before and after aging.|反應層越厚接合必越好~Assuming thicker reaction layers always improve bonding
冷卻殘餘應力~Residual stress during cooling|卸載與冷卻順序改變約束狀態，熱態良好接觸可能在降溫後轉為裂紋。~Unloading and cooling alter constraints; good hot contact can become cracked after cooling.|比較熱態、冷態翹曲及開路分布，先固定相同量測支撐條件。~Compare hot/cold warpage and open maps with consistent measurement supports.|熱態電性通過即可省略冷態重測~Skipping cold retest after a hot electrical pass
鏈路電測與局部定位~Chain testing and localization|菊鍊能放大連接失效但只给總阻值，局部 Kelvin 結構有助分離接點與路線。~Daisy chains expose interconnect failures but return aggregate resistance; local Kelvin structures help separate joints and traces.|先量鏈路再定位异常段，将量測底噪和重复性列入判定。~Measure chains, localize anomalous segments and include instrument floor and repeatability in decisions.|菊鍊合格證明每接點阻值完全一致~Assuming a passing chain proves identical joint resistance
接合窗口的轉移限制~Limits of process-window transfer|工具、材料、晶粒尺寸與間距變更會改變接觸和熱歷程，舊窗口須用見證件重新建立。~Tool, material, die-size and pitch changes alter contact and thermal histories; qualify transferred windows using witnesses.|列變更矩陣與保留條件，至少含幾何、電性、界面和熱循環證據。~Document changes and holds using geometric, electrical, interface and thermal-cycle evidence.|相同型號設備可直接共用全部設定~Transferring every setting unchanged between nominally identical tools
''', 'a106')
add(105,'銅表面形貌、接觸形成與界面電阻~Copper topography, contact formation and interface resistance','表面與界面設計~Surface and interface design|接觸形成~Contact formation|電性與力學證據~Electrical and mechanical evidence|整合與壽命~Integration and lifetime','besipub imec3d', [('a107','都依賴清潔、平坦度與銅接點重疊~Both depend on cleanliness, flatness and Cu-pad overlap','直接金屬接合不等於同時存在介電質接合的混合界面~Direct metal bonding is not identical to a hybrid metal–dielectric interface'),('a103','皆需銅微結構與電遷移驗證~Both require Cu microstructure and electromigration verification','銅柱通常有較大形貌與可選焊料帽，直接接合須另建表面接觸模型~Pillars have larger topography and optional solder caps; direct bonding needs its own contact model')], '假設總接點電阻 12 mΩ，四端量得銅體與走線為 7±1 mΩ，界面差值估計 5 mΩ；若總值不確定度為 1 mΩ 且獨立，差值標準不確定度為 √2≈1.41 mΩ。~Assume total resistance 12 mΩ and four-terminal body/trace contribution 7±1 mΩ. The inferred interface contribution is 5 mΩ; with independent 1 mΩ total uncertainty, its standard uncertainty is √2≈1.41 mΩ.', '''
銅與介電界面區分~Separate Cu and dielectric interfaces|直接銅接合的承載與導電區必須明確界定，不能把混合接合的介電質支撐默認套入。~Define the load-bearing and conductive regions explicitly; do not silently import dielectric support from hybrid bonding.|畫有無介電支撐兩種剖面，標出接觸應力和電流路徑。~Draw sections with and without dielectric support and mark contact stress and current paths.|所有無焊料接合都具有相同混合界面~Treating every solderless bond as the same hybrid interface
表面氧化與等待時間~Oxidation and queue time|表面狀態會隨清潔後暴露環境改變，等待時間是整合變數而不是行政記錄。~Surface state changes with exposure after preparation; queue time is an integration variable, not merely a log entry.|將批次、暴露與接合電阻关联，必要時用表面分析區分氧化和有機物。~Correlate lot, exposure and resistance, using surface analysis to distinguish oxides from organics.|清潔完成後表面狀態會永久不變~Assuming a prepared surface remains unchanged indefinitely
粗糙度頻譜~Roughness spectrum|相同 RMS 粗糙度可能來自不同空間波長；接觸面積還受起伏尺度與翹曲控制。~Equal RMS roughness can contain different spatial wavelengths; contact area also depends on waviness and warpage.|比較掃描尺寸、濾波條件與高度分布，避免把不同量測帶寬直接合併。~Compare scan size, filtering and height distributions rather than merging different measurement bandwidths.|相同 RMS 值代表相同真實接觸面積~Equating equal RMS roughness with equal real contact area
銅凹陷與突出~Cu recess and protrusion|金屬相對周邊的高度決定最先接觸區和局部承壓，平均平坦不保證每個焊墊足夠接觸。~Metal height relative to surroundings determines initial contact and local load; mean flatness does not guarantee all-pad contact.|以跨焊墊線掃描量相對高度，記錄相鄰介電質作基準的方法。~Measure cross-pad height relative to adjacent dielectric and document the reference plane.|全片翹曲小即可不量局部銅凹陷~Ignoring local Cu recess when wafer warpage is small
重疊面積預算~Overlap-area budget|對位誤差減少有效電接觸面積並提高局部電流擁擠，旋轉誤差在遠離中心處更大。~Overlay reduces conducting area and increases crowding; rotational error grows farther from the center.|由實測向量計算每顆焊墊交集面積，比較中心與角落。~Calculate pad-intersection areas from measured vectors and compare center and corners.|中心對位合格即可推論四角重疊~Inferring corner overlap from a passing center alignment
真實接觸與塑性~Real contact and plasticity|粗糙峰先接觸，局部塑性及擴散會改變界面；名義壓力不足以描述接觸演化。~Asperities touch first; local plasticity and diffusion evolve the interface, beyond nominal-pressure descriptions.|比較載入前後形貌、接觸電阻與殘餘印痕，用同幾何對照件。~Compare pre/post-load topography, resistance and residual impressions using matched geometries.|提高名義壓力必定線性降低接觸電阻~Assuming pressure reduces contact resistance linearly without limit
晶粒取向與界面遷移~Grain orientation and interface migration|銅晶粒的取向和界面遷移會影響接合演化，初始接觸消失不等於所有區域皆連續。~Grain orientation and boundary migration affect bond evolution; a locally vanished seam does not prove full-area continuity.|用多位置截面或取向分析對照電性，標注取樣偏差。~Compare multisite sections or orientation analysis with electrical data and note sampling bias.|一張無接縫截面足以代表整片界面~Using one seam-free section to certify the whole interface
Kelvin 接觸電阻~Kelvin contact resistance|四端結構能減少引線影響，但電流擁擠與幾何展開仍可能混入界面估算。~Four-terminal structures reduce lead effects, but current spreading and geometry can still enter interface estimates.|比较不同接點尺寸的 R×面積趨勢，檢查是否存在固定串聯項。~Compare R×area across contact sizes and check for a fixed series contribution.|四端量測自動排除所有幾何寄生~Assuming four-terminal measurement removes every geometric parasitic
空洞與偵測極限~Voids and detection limits|聲學、截面與電性看到不同空洞尺度；沒有檢出只代表低於當次方法的靈敏度。~Acoustic, cross-section and electrical methods respond to different void scales; nondetection is limited by sensitivity.|對照方法的解析度、掃描範圍與埋深，設計已知缺陷見證件。~Compare resolution, coverage and depth sensitivity using known-defect witnesses.|聲學無異常可排除奈米界面空隙~Using a clean acoustic image to exclude nanoscale interface gaps
界面強度與能量~Interface strength and energy|拉力或剪力峰值依試片幾何，界面斷裂能須考慮裂紋路徑與模式混合。~Peak tensile/shear loads depend on specimen geometry; fracture energy also requires crack-path and mode-mix information.|標記裂紋是否留在界面，報告載入方向、面積和破面影像。~Identify whether cracks stay at the interface and report direction, area and fracture images.|把不同試片的峰值力當成材料固有強度~Treating peak forces from different specimens as intrinsic material strength
熱循環與電流耦合~Thermal cycling and current coupling|熱失配可先降低有效面積，再由電流集中加劇發熱；機械與電性退化不是獨立事件。~Thermal mismatch can reduce area before current crowding increases heating; mechanical and electrical degradation are coupled.|先後量測冷態電阻、通電溫升與裂紋，保留試驗順序。~Measure cold resistance, powered temperature rise and cracking while preserving test order.|分開通過機械和電性測試就可忽略耦合~Ignoring coupling after separate mechanical and electrical passes
接合界面交接~Interface qualification handoff|可接受條件須同時包含面積覆蓋、阻值分布、強度及後續熱預算，不只設備顯示完成。~Acceptance combines coverage, resistance distribution, strength and downstream thermal budget, not a completed tool cycle.|建立批次證據包並列出未覆蓋的面積或應力範圍。~Assemble lot evidence and declare untested area or stress ranges.|設備流程完成即代表界面已合格~Equating completed processing with a qualified interface
''', 'a106')
add(107,'已知良品、局部對位與混合介面~Known-good die, local overlay and hybrid interfaces','晶粒輸入~Die inputs|表面準備~Surface preparation|精密貼合~Precision bonding|良率證據~Yield evidence','besihyb imecd2w', [('a106','介電質接合與銅重疊的證據可轉移~Evidence for dielectric bonding and Cu overlap transfers','晶粒對晶圓增加切割污染、拾取及逐顆對位，不能照搬全片接合良率~D2W adds singulation contamination, pickup and per-die overlay beyond W2W'),('a113','取放座標、旋轉和表面保護直接傳入接合~Pickup coordinates, rotation and surface protection feed directly into bonding','放置精度尚不等於退火後電接點重疊~Placement precision is not post-anneal electrical overlay')], '假設 20 顆晶粒各自良率 0.99 且獨立，全數良好機率 0.99²⁰≈0.818。若每顆選片後為 0.999，則≈0.980；這只算晶粒，不含接合相關缺陷。~For 20 independent dies at 0.99 yield, all-good probability is 0.99²⁰≈0.818; at 0.999 after selection it is≈0.980. Bonding and correlated defects are excluded.', '''
已知良品置信度~Known-good-die confidence|測試覆蓋率與逃逸率決定選片可信度，通過並非零缺陷。~Test coverage and escapes determine selection confidence; passing is not defect-free.|比較前測、接合後測與失效定位。~Compare pre-bond, post-bond and localization data.|把前測通過當成永久良品~Treating a pretest pass as permanently good
切割後表面~Post-singulation surfaces|切割顆粒可成為接合空洞起點，晶粒邊緣與中心須分開採樣。~Dicing particles can initiate voids; sample edges and centers separately.|對照顆粒圖與空洞圖的空間相關。~Compare particle and void maps spatially.|顆粒總數相同就有相同接合風險~Equating equal particle counts with equal bonding risk
活化與等待~Activation and queue time|表面化學會隨保存環境演化，活化效果須連到實際等待歷程。~Surface chemistry evolves during storage; activation must be linked to queue history.|記錄活化到貼合時間及見證接合。~Record activation-to-bond delay and witness results.|活化條件相同即可忽略保存環境~Ignoring storage with identical activation settings
局部銅凹陷~Local Cu recess|單顆晶粒的焊墊高度分布影響接觸，晶圓平均不能替代逐顆尾端風險。~Per-die pad-height distribution controls contact; wafer means hide die-level tails.|量中心和四角焊墊的相對高度。~Measure pad-relative height at center and corners.|平均高度合格即排除局部未接觸~Using mean height to rule out local noncontact
翻面與座標~Flip and coordinates|翻面改變座標手性，旋轉補償須以非對稱標記驗證。~Flipping changes handedness; validate rotation using asymmetric marks.|模擬一個非對稱 pad 圖的翻轉。~Transform an asymmetric pad map explicitly.|翻面等同平面旋轉 180 度~Equating a flip with a 180-degree planar rotation
誤差分解~Overlay decomposition|拾取、相機、平台與熱漂移的誤差須分解系統項和隨機項。~Separate systematic and random pickup, camera, stage and thermal errors.|作重複放置和時間序列控制圖。~Use repeat placements and time-series control charts.|所有誤差都可用 RSS 相加~Combining all errors by RSS regardless of correlation
接合波與局部接觸~Bond-wave contact|接觸從局部展開時會受翹曲與顆粒阻擋，表面潔淨度和力學不可分開。~Propagating contact is obstructed by warp and particles; cleanliness and mechanics interact.|比較空洞形狀與接觸起點。~Compare void shapes with contact initiation points.|只看最終位置即可判斷接合完整~Inferring bond completeness from final position
銅接點電性~Cu-joint electrical behavior|電性開路可能來自錯位、空洞或銅接觸不足，須對應局部圖。~Opens may reflect overlay, voids or insufficient Cu contact; correlate local maps.|把 Kelvin 點、菊鍊與影像對位。~Register Kelvin, chain and imaging sites.|開路只能由晶粒對位造成~Attributing every open to die misalignment
介電質界面~Dielectric interface|介電質接合提供支撐，銅電性合格仍可能存在未接合區。~Dielectric bonding supports the stack; passing Cu conductivity may coexist with unbonded regions.|對照聲學、裂紋與電性採樣。~Compare acoustic, crack and electrical sampling.|銅接通就證明全部介電質接合~Using Cu continuity to prove complete dielectric bonding
修補與不可逆點~Rework and irreversible points|選片改善來料良率，但已成形界面可能難以修補，需先定義保留點。~Selection improves input yield, but formed interfaces may be hard to rework; define hold points first.|畫出可重測、可更換與不可逆節點。~Map retest, replacement and irreversible nodes.|接合後任意晶粒都可無損更換~Assuming every bonded die is nondestructively replaceable
堆疊良率模型~Stack-yield model|獨立乘法模型是起點，共因顆粒或翹曲會使缺陷相關。~Independent yield multiplication is a starting model; particles and warp introduce correlation.|比較獨立預測與晶圓群聚失效。~Compare independent predictions with clustered wafer failures.|晶粒良率乘積必精確等於組裝良率~Equating the die-yield product with exact assembly yield
熱與資料交接~Thermal and data handoff|後續熱循環可改變應力和電阻，需保留逐顆幾何及材料履歷。~Later thermal cycles alter stress and resistance; retain per-die geometry and material history.|提交前後測配對資料及未驗證熱範圍。~Submit paired tests and unverified thermal ranges.|初始良率即可代表產品壽命~Treating initial yield as product lifetime
''','a106')
add(108,'堆疊拓撲、累積誤差與可測性~Stack topology, accumulated error and testability','堆疊定義~Stack definition|層間組裝~Interlayer assembly|跨層驗證~Cross-layer verification|熱與可靠度~Thermal and reliability','imec3d besipub', [('a107','共用良品篩選、表面與對位證據~Shares die screening, surface and overlay evidence','晶粒對晶粒處理對象更小且兩側支撐不同~D2D uses smaller workpieces with different support on both sides'),('a132','堆疊熱阻和熱源位置直接耦合~Stack thermal resistance couples directly to heat-source position','本課組裝可行性不取代熱管理的系統邊界~Assembly feasibility does not replace system thermal boundaries')], '假設 8 層厚度各 50±1 μm，獨立標準差的總厚不確定度 √8≈2.83 μm；若每層有同向 1 μm 系統偏差，總偏差為 8 μm，不能用 RSS 消除。~Eight illustrative 50±1 μm layers give √8≈2.83 μm total standard uncertainty if independent. A same-sign 1 μm systematic bias per layer instead adds to 8 μm.', '''
面向與拓撲~Orientation and topology|面對面與背對面堆疊改變 TSV 需求和可用電極。~Face-to-face versus back-to-face changes TSV needs and accessible pads.|畫每層訊號、電源和背面。~Draw signals, supplies and backsides for every layer.|所有堆疊方向可共用同一接線圖~Reusing one net map for every orientation
層間接口契約~Interlayer interface contract|尺寸、電壓、時序和熱負荷須同時相容。~Dimensions, voltage, timing and thermal load must all be compatible.|列上下層雙方簽認的接口表。~Create an interface table agreed by both layers.|幾何能接合即表示電路相容~Equating mechanical mating with circuit compatibility
厚度堆積~Thickness accumulation|隨機與系統厚度誤差累積方式不同。~Random and systematic thickness errors accumulate differently.|區分同機台偏差與逐片變異。~Separate tool bias from wafer-to-wafer variation.|全部厚度公差都可平方和開根~Applying RSS to every thickness tolerance
已知良品序列~Known-good-die sequence|昂貴上層疊入前的測試可以避免浪費後續工序。~Testing before adding costly layers avoids wasted downstream work.|計算各保留點的成本與逃逸風險。~Compare hold-point cost and escape risk.|最終測試即可取代全部中間測試~Replacing every intermediate test with final testing
拾取支撐~Pickup support|薄晶粒的彎曲和表面損傷取決於吸附與頂針受力路徑。~Thin-die bending and damage depend on suction/ejector load paths.|比較中心支撐與邊缘懸空的示意。~Compare center support and overhanging edges.|平均吸力相同即有相同彎曲風險~Equating average suction with equal bending risk
逐層對位~Layer-by-layer overlay|相對每層對準不保證對共同基準的累積誤差小。~Good adjacent-layer overlay need not ensure small error to a common datum.|同時繪相鄰誤差與全堆疊基準誤差。~Plot adjacent-layer and common-datum errors.|每層偏移小就不用量整體漂移~Ignoring global drift when individual shifts are small
接合界面抽樣~Interface sampling|埋藏層的取樣可接近性隨堆疊改變，須預留見證結構。~Buried-interface access changes during stacking; reserve witness structures.|列每一界面的可測量與盲區。~List measurable quantities and blind spots per interface.|最上層影像可代表所有埋藏界面~Using top-layer images for every buried interface
跨層供電~Vertical power delivery|多層電流匯流造成不同 TSV 和接點電流負載。~Summed layer currents impose unequal TSV and joint loading.|依每層功耗畫垂直電流樹。~Draw a vertical current tree from layer power.|所有層用電相同即各 TSV 同電流~Assuming equal layer power gives equal TSV currents
測試存取~Test access|埋藏邏輯需設計可觀測和可控制路徑，邊界測試不等於完整功能測試。~Buried logic needs observable and controllable paths; boundary testing is not full functionality.|比較連通測試、記憶體測試與功能測試覆蓋。~Compare continuity, memory and functional coverage.|邊界鏈路通過即所有邏輯功能正常~Equating boundary-chain success with all logic functionality
熱源與熱阻~Heat sources and resistances|熱源位置改變每層溫度；只有總功耗無法決定熱點。~Heat-source location changes layer temperatures; total power alone cannot locate hotspots.|在同總功耗下交換上、下層熱源。~Swap top/bottom sources at equal total power.|總功耗相同便有相同最高溫~Assuming equal total power yields equal peak temperature
層間應力~Interlayer stress|材料不對稱及厚度差產生曲率和界面剪應力。~Material asymmetry and thickness differences generate curvature and interface shear.|比較對稱與不對稱堆疊的翹曲圖。~Compare symmetric and asymmetric stack warpage.|加厚最上層總能降低所有界面應力~Assuming a thicker top layer lowers every interface stress
失效拆解順序~Failure-analysis order|破壞性拆解會消除某些證據，應先電測和非破壞定位。~Destructive sectioning removes evidence; localize electrically and nondestructively first.|制定先後順序及保留對照片。~Plan analysis order and retained controls.|先研磨到可見裂紋再作電測最有效~Grinding first before electrical localization
''','a106')
add(109,'載板支撐、黏著窗口與低損傷解接合~Carrier support, adhesion window and low-damage release','材料與路徑~Materials and routes|暫時接合~Temporary bonding|背面加工~Backside processing|解接合與清潔~Debond and cleaning','evgtemp corningcarrier', [('a110','載板剛性和膠層均勻度傳入薄化厚度~Carrier stiffness and adhesive uniformity affect thinning thickness','本課還需兼顧可拆解性，研磨課著重材料移除與損傷~This course includes releasability; grinding emphasizes removal and damage'),('a116','扇出重組同樣用載板管理薄膜與晶粒~Fan-out reconstitution similarly uses carriers for films and dies','晶圓連續片與重組晶粒的局部台階和流動邊界不同~Continuous wafers and reconstituted dies have different steps and flow boundaries')], '假設兩材料 Δα=5 ppm/K、長 100 mm、ΔT=100 K，自由差異伸長 ΔL=ΔαLΔT=50 μm；黏著拘束會把其中部分轉為應力，不能把此數直接視為實際滑移。~For Δα=5 ppm/K, L=100 mm and ΔT=100 K, free differential expansion is 50 μm. Adhesive constraints convert part into stress; this is not the actual slip.', '''
載板材料選擇~Carrier selection|透明度、CTE、剛性和清潔相容性決定載板用途。~Transparency, CTE, stiffness and cleaning compatibility determine carrier suitability.|按加工與釋放需求建立材料矩陣。~Build a material matrix against processing and release needs.|玻璃載板可自動相容所有雷射波長~Assuming glass is compatible with every laser wavelength
釋放路徑比較~Release-route comparison|熱滑移、UV 與 IR 釋放的作用層和設備邊界不同。~Thermal-slide, UV and IR release act at different layers and boundaries.|把吸收層、透明路徑和支撐面標到剖面。~Mark absorbers, optical paths and supports in section.|各種解接合只差光源名稱~Treating release routes as interchangeable light-source labels
膠層厚度地圖~Adhesive thickness map|膠層厚度變化會轉成加工支撐和厚度誤差。~Adhesive variations become support and processing-thickness errors.|分開量載板、膠層與晶圓厚度。~Measure carrier, adhesive and wafer thickness separately.|總厚度均勻即可證明膠層均勻~Inferring uniform adhesive from uniform total thickness
空洞與氣泡~Voids and bubbles|未接合空洞降低局部剛性，背面載荷可放大變形。~Bond voids reduce local stiffness, amplifying backside-load deformation.|將空洞圖與薄化後厚度圖配準。~Register void and post-thinning thickness maps.|小空洞在所有後續步驟都無影響~Assuming small voids never matter downstream
邊緣封閉~Edge coverage|邊緣缺膠可能成為液體入侵及應力起點。~Edge adhesive gaps can admit fluids and initiate stress concentration.|檢查圓周覆蓋及邊緣排除區。~Inspect circumferential coverage and exclusion zones.|只測中心接合強度即可代表整片~Using center bond strength to represent the wafer
熱预算相容性~Thermal-budget compatibility|暫時膠需承受加工歷程又保留釋放能力。~Temporary adhesive must survive processing while retaining releasability.|比較加工前後的剪切、滑移和殘膠。~Compare shear, slip and residue before/after processing.|加工時黏得越強解接合一定越好~Assuming stronger process adhesion always improves release
化學與真空相容性~Chemical and vacuum compatibility|溶脹、揮發和污染可能改變支撐而非直接可見裂紋。~Swelling, outgassing and contamination can change support without visible cracks.|用見證件比質量、厚度和污染。~Compare witness mass, thickness and contamination.|外觀無裂紋即證明材料相容~Using crack-free appearance as compatibility proof
薄片應力~Thin-wafer stress|薄片彎曲剛性近似隨厚度三次方下降。~Thin-plate bending stiffness approximately scales with thickness cubed.|比較厚度減半時支撐需求的變化。~Compare support needs when thickness halves.|厚度減半僅讓剛性減半~Assuming half thickness means half stiffness
解接合支撐~Release support|釋放瞬間載荷路徑改變，應避免自由薄片懸空。~Release abruptly changes load paths; avoid unsupported thin-wafer spans.|畫解接合前中後三種支撐。~Draw supports before, during and after release.|只控制釋放能量即可忽略接收支撐~Ignoring receiving support when release energy is controlled
殘膠判定~Residue assessment|殘膠可影響後段接合與量測，透明外觀不等於潔淨。~Residue affects later bonding and metrology; optical transparency is not cleanliness.|比較接觸角、表面分析和後段見證片。~Compare contact angle, surface analysis and downstream witnesses.|肉眼透明即可免除殘留檢測~Skipping residue checks for a transparent surface
載板再用~Carrier reuse|重複清潔可能累積表面損傷、邊緣缺陷或翹曲。~Repeated cleaning can accumulate surface damage, edge defects or warp.|以循環次數追蹤平坦度與缺陷。~Track flatness and defects by reuse cycle.|每次清潔後載板等同全新~Treating every cleaned carrier as new
完整轉移證據~Transfer evidence|薄片無破裂、表面可接合和厚度合格是不同結果。~Intact transfer, bondable surfaces and correct thickness are distinct outcomes.|提供三類資料與後段驗證保留點。~Deliver all three evidence types and downstream hold points.|沒有破片即表示暫時接合全程成功~Calling the process successful solely because no wafer broke
''','a106')
add(110,'薄化幾何、次表面損傷與薄片支撐~Thinning geometry, subsurface damage and thin-wafer support','厚度需求~Thickness requirements|研磨與支撐~Grinding and support|損傷去除~Damage removal|背面驗收~Backside acceptance','disco dbg', [('a109','膠層與載板均勻性是研磨幾何的前置輸入~Adhesive and carrier uniformity precede grinding geometry','暫時接合重在支撐釋放，本課分析材料移除與損傷~Temporary bonding emphasizes support/release; this course analyzes removal/damage'),('a123','薄化接近 TSV 深度後需轉入精細露出控制~Thinning near TSV depth hands off to controlled reveal','整体減薄與局部金屬露出有不同終點和選擇比需求~Bulk thinning and local metal reveal need different endpoints/selectivities')], '同材料薄片在小撓度板模型下 D∝t³。厚度由 100 μm 降至 50 μm，彎曲剛性為原來 1/8；實際破壞還受裂紋、支撐與殘應力控制。~For the same material under small-deflection plate theory, D∝t³. Reducing 100 μm to 50 μm gives one eighth the stiffness; fracture also depends on flaws, support and residual stress.', '''
最終厚度分配~Final-thickness allocation|目標厚度須扣除後續應力釋放和露出加工留量。~Final thickness must reserve later stress-relief and reveal allowances.|畫厚度預算的逐站瀑布圖。~Draw a station-by-station thickness waterfall.|研磨終點就是最終封裝厚度~Equating the grinding endpoint with final package thickness
TTV 與翹曲~TTV versus warpage|總厚度變異與自由形狀翹曲是不同量。~Total-thickness variation and free-shape warpage are different measurands.|比較夾持與自由狀態雙面量測。~Compare clamped and free-state two-sided measurements.|單面高度圖可直接當 TTV~Treating a one-sided height map as TTV
正面保護~Frontside protection|保護層需承擔局部凸塊地形且避免污染功能面。~Protection must accommodate bump topography without contaminating the functional face.|比較凸塊周圍支撐和剝離後表面。~Compare support near bumps and post-peel surfaces.|保護膜厚即可保證所有凸塊不受力~Assuming film thickness prevents every bump from loading
粗磨與細磨~Coarse and fine grinding|移除效率和損傷深度互相牽制，細磨不保證去除全部粗磨損傷。~Removal rate trades against damage depth; fine grinding need not remove all coarse damage.|對照逐站移除量與截面損傷。~Compare removal per station with damage sections.|最後表面光滑就無次表面裂紋~Equating smooth surfaces with no subsurface cracks
載荷與輪痕~Loads and wheel marks|輪痕方向與局部負載可留下應力各向異性。~Wheel-mark direction and local loads can create anisotropic stress.|按徑向和切向取樣比較強度。~Compare radial and tangential strength sampling.|所有方向的彎曲強度可視為相同~Assuming equal bending strength in every direction
厚度量測基準~Thickness reference|透明保護層、背面反射與探頭校正會影響厚度讀值。~Transparent protection, backside reflections and probe calibration affect readings.|用可追溯標準片與另一方法交叉校核。~Cross-check with traceable standards and a second method.|高解析讀值等同高準確度~Equating high readout resolution with high accuracy
邊緣缺口~Edge chipping|邊緣裂紋受後續搬運彎曲放大，中心強度不能代表邊緣。~Edge flaws are amplified by handling bending; center strength does not represent edges.|保留圓周缺陷圖與搬運方向。~Retain circumferential defect maps and handling directions.|中心厚度合格可忽略邊緣裂紋~Ignoring edge cracks after a center-thickness pass
應力釋放~Stress relief|移除受損表面可提高強度但同時改變厚度和背面化學。~Removing damaged material can improve strength while changing thickness and chemistry.|比較前後曲率、厚度與強度分布。~Compare curvature, thickness and strength distributions.|應力釋放只改機械性能不改幾何~Assuming stress relief changes mechanics but not geometry
周邊保留環~Retained peripheral ring|保留周邊厚環可增加薄片搬運剛性，但會改變後續分離路徑。~A thick peripheral ring improves handling stiffness but changes separation flow.|畫薄區、過渡區及厚環的受力。~Draw loads in thin, transition and ring regions.|厚環支撐等同全片均勻厚度~Treating ring-supported wafers as uniformly thick
破裂統計~Fracture statistics|脆性強度由缺陷分布控制，平均值不足以描述低端失效。~Brittle strength depends on flaw distribution; means hide the weak tail.|比較相同測試幾何下的分位數與樣本量。~Compare quantiles and sample sizes at identical test geometry.|最高強度樣本可代表整批可靠度~Using the strongest sample to represent lot reliability
薄片轉移~Thin-wafer transfer|真空夾持、載板和膜框切換改變支撐跨距。~Vacuum chucks, carriers and frames change unsupported spans.|逐站標出跨距及厚度最薄處。~Mark spans and thinnest locations at each station.|晶圓未破就表示沒有潛在搬運損傷~Assuming unbroken wafers have no latent handling damage
後段交接~Downstream handoff|TSV、光學或背金屬用途對背面粗糙度和殘留有不同要求。~TSV, optical and backside-metal uses impose different roughness/residue requirements.|按下站功能分別列接受條件。~Define acceptance by the next station's function.|所有薄晶圓可用一套背面規格~Using one backside specification for all thin wafers
''')
add(111,'內部改質層、裂紋傳播與薄晶粒強度~Internal modified layers, crack propagation and thin-die strength','材料與路徑~Material and path|內部改質~Internal modification|分離與邊緣~Separation and edges|驗證與整合~Validation and integration','disco dbg', [('a112','皆以圖形化分離取代傳統鋸切部分限制~Both address limitations of conventional sawing','隱形切割依內部改質與裂開，電漿切割依遮罩與移除~Stealth uses internal modification/fracture; plasma uses masking/removal'),('a110','SDBG 把內部改質放在研磨前，厚度與裂紋需共同設計~SDBG places modification before grinding, coupling thickness and cracks','研磨移除材料，隱形切割建立可控裂開路徑~Grinding removes material; stealth dicing establishes a fracture path')], '假設街道寬 40 μm、對準誤差界限 ±3 μm、受影響區寬 12 μm，單側理想幾何餘量為 (40−12)/2−3=11 μm；還未包含裂紋偏折和保護區。~For a hypothetical 40 μm street, ±3 μm alignment bound and 12 μm affected zone, one-sided geometric margin is (40−12)/2−3=11 μm before crack deviation and keep-outs.', '''
光穿透條件~Optical penetration|焦點須位於材料內部，入射面與材料吸收決定可達深度。~The focus must lie inside the material; entry surface and absorption limit depth.|畫光路及表面膜層，辨認遮擋。~Draw the optical path and films, identifying obstruction.|所有晶圓材料都可共用同一光路~Using one optical path for every wafer material
街道與功能區~Streets and active areas|改質和裂開區必須留在電路保護邊界外。~Modification and fracture zones must remain outside circuit keep-outs.|疊合街道、密封環及定位誤差。~Overlay streets, seal rings and positioning error.|街道中心對準就無需保護餘量~Omitting keep-out margin after center alignment
厚度與焦深~Thickness and focal depth|厚度變化改變內部焦點位置相對背面的距離。~Thickness variation changes focus distance from the backside.|將厚度地圖與焦點基準配準。~Register thickness maps and focal references.|名義厚度相同便可省略全片地圖~Skipping wafer maps at equal nominal thickness
改質層概念~Modified-layer concept|局部材料改變形成裂開起始，並非以表面燒蝕切出完整溝槽。~Local modification initiates fracture rather than ablating a full surface trench.|用截面區分表面去除和內部改質。~Distinguish surface removal and internal modification in section.|隱形切割等同表面燒蝕~Equating stealth dicing with surface ablation
晶向與裂紋~Orientation and cracks|裂紋路徑會受晶向和應力狀態影響，不能僅依光束軌跡預測。~Cracks depend on crystal orientation and stress, not just beam trajectory.|比較正交街道邊緣形貌。~Compare edge morphology along orthogonal streets.|裂紋永遠完全沿雷射掃描線~Assuming cracks follow the scan line exactly
改質連續性~Modification continuity|不連續弱化區可能造成未分離或偏折裂紋。~Discontinuous weakening can cause incomplete separation or deflection.|以分離後未斷區反推改質連續性。~Use unseparated segments to evaluate continuity.|表面看不見痕跡即表示改質失敗~Treating invisible surface marks as failed modification
研磨前後順序~Grinding order|SDBG 的加工順序使研磨和裂紋發展共同影響最後邊緣。~SDBG couples grinding and crack evolution through process order.|比較先薄化與後薄化兩條流程。~Compare thin-first and thin-later flows.|交換順序不影響薄晶粒強度~Assuming order never affects thin-die strength
膜框擴張~Tape expansion|膜框擴張把載荷傳入街道，非均勻張力可造成不同分離量。~Tape expansion loads streets; uneven tension causes uneven separation.|量中心與邊緣晶粒間隙和旋轉。~Measure center/edge die gaps and rotation.|擴張距離相同即每條街道受力相同~Equating frame expansion with equal street forces
崩邊與裂紋深度~Chipping and crack depth|邊緣外觀只顯示表面，次表面裂紋仍可能控制抗折強度。~Edge appearance shows the surface; subsurface cracks may control strength.|結合邊緣影像和匹配方向彎曲試驗。~Combine edge images with direction-matched bend tests.|無可見崩邊即無潛在裂紋~Equating no visible chipping with no latent cracks
粒子與拾取~Particles and pickup|分離後顆粒與膜黏著會影響後續高潔淨接合。~Post-separation particles and tape adhesion affect clean bonding.|比較拾取前後顆粒和晶粒面向。~Compare particles and orientation before/after pickup.|無鋸屑就可省略顆粒檢測~Skipping particle inspection because there is no sawdust
電性保護~Electrical protection|切割傷害可能接近密封環或引發後續應力敏感缺陷。~Dicing damage may approach seal rings or trigger stress-sensitive defects.|配對切割前後電性及邊緣位置。~Pair pre/post electrical data with edge locations.|機械分離成功即電性一定不變~Assuming successful separation preserves electrical behavior
路徑驗收~Route qualification|材料、膜層和厚度改變需重新確認透光與裂開邊界。~Material, film and thickness changes require new optical/fracture validation.|建立變更矩陣和見證片組。~Build a change matrix and witness set.|已驗證矽流程可直接套用所有複合晶片~Transferring a qualified silicon flow to every composite die
''')
add(112,'遮罩、深蝕刻及膜框熱邊界~Masking, deep etch and frame thermal boundaries','分離設計~Singulation design|遮罩與載台~Mask and chuck|蝕刻行為~Etch behavior|邊緣與良率~Edges and yield','sptsdice oxdrie', [('a111','都需定義街道與裂紋保護區~Both need streets and crack keep-outs','電漿以材料移除成溝，隱形切割靠裂開~Plasma removes a trench while stealth relies on fracture'),('a121','共享深矽蝕刻中的負載與側壁控制~Shares loading and sidewall control of deep Si etch','切割要穿透並保護膜框，TSV 通常要保留孔底~Dicing breaks through and protects tape, whereas TSVs usually retain bottoms')], '假設晶圓厚 50 μm、街道開口 10 μm，名義深寬比為 5。若遮罩消耗 2 μm、矽移除 50 μm，表觀選擇比為 25；不能用它預測不同圖形負載。~A hypothetical 50 μm wafer and 10 μm opening give aspect ratio 5. Removing 50 μm Si with 2 μm mask loss gives apparent selectivity 25, not a prediction for different pattern loading.', '''
街道版圖~Street layout|遮罩開口需避開金屬與功能層，街道並非只有矽。~Mask openings must accommodate metals and functional films; streets are not pure silicon.|列街道逐層材料。~List the layer stack in each street.|矽可蝕刻就能直接穿透全部街道材料~Assuming Si etching removes every street material
圖形密度~Pattern density|開口面積比影響反應物供應與總熱負荷。~Open-area fraction affects reactant supply and heat load.|比較稀疏與密集街道的深度。~Compare depth for sparse and dense streets.|相同線寬必有相同蝕刻速率~Equating equal width with equal etch rate
遮罩預算~Mask budget|遮罩選擇比須保留過蝕與非均勻性餘量。~Mask selectivity needs margin for overetch and nonuniformity.|用最慢區深度和最大遮罩損失估算。~Use slowest-site depth and greatest mask loss.|平均選擇比可確保所有位置遮罩存活~Using mean selectivity to guarantee mask survival everywhere
膜框相容性~Tape-frame compatibility|膜材揮發、耐熱與夾持決定能否承受真空加工。~Tape outgassing, heat resistance and clamping govern vacuum compatibility.|對照見證膜的外觀、黏力及污染。~Check witness-film appearance, adhesion and contamination.|膜框能入腔就代表材料已相容~Equating chamber fit with material compatibility
散熱接觸~Thermal contact|薄晶圓與膜框的接觸熱阻影響局部溫度。~Contact resistance between thin wafer and frame affects local temperature.|比較熱見證與邊緣變色位置。~Compare thermal witnesses and edge discoloration.|載台溫度就是晶圓所有位置溫度~Equating chuck temperature with every wafer location
側壁循環~Sidewall cycles|交替移除和保護形成深溝，循環紋路與側壁角要分開評估。~Alternating removal and protection forms trenches; assess scallops separately from wall angle.|量上中下寬度和紋路幅度。~Measure top/mid/bottom width and scallop amplitude.|垂直側壁即可保證表面平滑~Equating vertical walls with smooth walls
深寬比效應~Aspect-ratio effects|深溝的傳輸限制使底部反應與表面不同。~Transport limitations make deep-trench bottoms differ from surfaces.|比較不同開口寬度的深度曲線。~Compare depth curves across opening widths.|速率只由總加工時間決定~Assuming etch depth depends only on time
穿透終點~Breakthrough endpoint|最先穿透處暴露膜框，最慢處仍未分離。~Early breakthrough exposes tape while slow sites remain attached.|定義最早、最晚終點和過蝕風險。~Define earliest/latest endpoints and overetch risk.|平均深度達厚度就表示全部切開~Equating mean depth with complete singulation
充電與電路~Charging and circuits|電漿環境可影響暴露結構，分離良率需搭配電性檢查。~Plasma exposure can affect structures; singulation yield needs electrical checks.|用匹配電路作前後電性比較。~Compare matched circuits before and after processing.|非機械切割就不會傷害電路~Assuming nonmechanical dicing cannot damage circuits
側壁殘留~Sidewall residues|殘留聚合物或遮罩可影響黏著和後續接合。~Polymer or mask residue affects adhesion and downstream bonding.|以表面分析和接合見證交叉比較。~Cross-check surface analysis and bonding witnesses.|裂縫已開通即可忽略側壁殘留~Ignoring residue after trench breakthrough
晶粒強度~Die strength|去除材料可減少鋸切類損傷，但強度仍受缺陷與側壁形貌控制。~Material removal avoids some saw damage, but strength still depends on flaws and sidewalls.|保持試片厚度與加載方向一致。~Keep specimen thickness and loading direction matched.|電漿切割必定讓所有晶粒同等強~Assuming plasma dicing gives identical strength to every die
良率與節拍~Yield and throughput|整片並行分離的節拍優势需扣除遮罩與清潔工序。~Parallel singulation benefits must include masking and cleaning time.|計算完整路徑時間與每良品成本。~Calculate full-route time and cost per good die.|只比較腔體時間即可比較工法成本~Comparing cost using chamber time alone
''')
add(113,'薄晶粒取放、座標轉換與受力保護~Thin-die handling, coordinate transforms and load protection','晶粒輸入~Die input|拾取受力~Pickup loading|定位放置~Positioning|檢測交接~Inspection handoff','besihyb besitcb', [('a107','取放誤差與顆粒直接影響混合接合~Placement errors and particles directly affect hybrid bonding','取放完成仍須額外檢查接合介面~Successful placement still requires interface qualification'),('a110','厚度與損傷決定晶粒搬運剛性~Thickness and damage determine handling stiffness','研磨驗收的自由晶圓狀態不同於頂針和吸嘴受力~Free-wafer grinding acceptance differs from ejector/nozzle loading')], '假設平台、視覺、取放的獨立標準差為 0.4、0.3、0.5 μm，RSS≈0.707 μm；若另有 1 μm 固定偏差，須先校正，不可把它當可平均掉的隨機值。~Independent illustrative stage, vision and placement standard deviations of 0.4, 0.3 and 0.5 μm give RSS≈0.707 μm. A separate 1 μm fixed bias requires calibration, not averaging.', '''
晶粒地圖身分~Die-map identity|晶粒座標需連結測試結果與取放紀錄以避免錯選。~Die coordinates must link test results to placement logs.|核對原點、列行與缺口方向。~Check origin, row/column and notch direction.|地圖尺寸相同就表示座標定義相同~Equating equal map dimensions with equal coordinates
膜黏著分布~Tape adhesion distribution|黏著力和剝離速度、溫度、照射歷程相關。~Adhesion depends on peel rate, temperature and exposure history.|比較同位置重複拾取的力曲線。~Compare force traces for matched pickup sites.|膜料號相同即可忽略保存歷程~Ignoring storage history for identical tape type
頂針受力~Ejector loading|頂針集中載荷可能使薄晶粒局部彎曲或裂開。~Concentrated ejector loading can bend or crack thin dies.|畫針位、吸嘴支撐與懸空區。~Draw pin sites, nozzle support and free spans.|總頂力小就不會局部破裂~Assuming small total force excludes local fracture
吸嘴接觸~Nozzle contact|吸嘴需避開敏感結構並提供足夠平面支撐。~Nozzles must avoid sensitive structures while providing planar support.|將接觸輪廓疊到元件版圖。~Overlay contact footprints on device layouts.|吸力足夠即可忽略接觸位置~Ignoring contact position when suction is sufficient
拾取與剝離~Pickup and peeling|同步移動的時間差改變剝離角及瞬間負載。~Motion timing changes peel angle and transient load.|對齊位移、力和高速影像時間軸。~Align displacement, force and high-speed images.|最終位移相同就具有相同應力歷程~Equating final travel with identical stress history
顆粒轉移~Particle transfer|吸嘴和膜都可能將顆粒帶到功能面。~Nozzles and tape can transfer particles to functional surfaces.|區分拾取前缺陷與拾取後新增點。~Separate pre-existing from pickup-added particles.|膜上顆粒不會進入接合介面~Assuming tape particles cannot reach bond interfaces
視覺標記~Vision fiducials|反光與遮擋使幾何中心不等於標記識別中心。~Reflections and occlusion shift detected fiducial centers.|比較不同光照下的座標漂移。~Compare coordinate drift under different illumination.|影像解析度高即可消除識別偏差~Assuming high image resolution eliminates recognition bias
剛體轉換~Rigid transforms|平移旋轉可描述剛體，但翹曲與縮放需額外模型。~Translation/rotation describe rigid bodies; warp and scaling require more.|以至少三個非共線標記檢查殘差。~Check residuals using at least three noncollinear marks.|兩點對準可以證明全片無變形~Using two-point alignment to prove no deformation
熱漂移校正~Thermal drift calibration|相機與平台熱漂移會隨運轉時間變化。~Camera/stage drift can evolve with runtime.|用固定參考點穿插量測長時間序列。~Interleave fixed references through long runs.|開機時校正足以涵蓋全天運行~Assuming startup calibration covers the whole day
放置接觸~Placement contact|接觸速度和基板順應性決定反彈與滑移風險。~Contact speed and substrate compliance govern rebound and slip.|比較接觸前與卸載後晶粒位置。~Compare precontact and post-unload position.|相機看到到位即可判斷卸載後不滑~Assuming visual arrival guarantees no post-unload slip
放置精度統計~Placement statistics|重複精度與絕對準確度不同，尾端樣本須保留。~Repeatability differs from absolute accuracy; retain distribution tails.|分開偏差、標準差及最壞殘差。~Report bias, standard deviation and worst residual separately.|只報 3σ 即可隱去平均偏差~Using 3σ while omitting mean bias
後段可接合性~Downstream bondability|精準位置、無裂紋與潔淨表面需共同驗證。~Position accuracy, crack absence and cleanliness need joint validation.|交付逐顆座標、缺陷與來源追溯。~Deliver per-die coordinates, defects and source traceability.|放置良率等於最終接合良率~Equating placement yield with final bonding yield
''','a106')
add(114,'毛細流動、填料與固化應力~Capillary flow, fillers and cure stress','間隙與潤濕~Gap and wetting|流動與排氣~Flow and venting|固化與應力~Cure and stress|檢測可靠度~Inspection and reliability','henkel henkeltech', [('a115','聚合物 CTE、固化和水分影響應力~Polymer CTE, cure and moisture affect stress','底膠受微間隙毛細作用，模封有不同流動與壓力边界~Underfill flows in narrow capillary gaps; molding has different pressure/flow boundaries'),('a104','接合間隙和聚合物流動相互影響~Bond gaps and polymer flow interact','接合後毛細填膠不能等同預置膜的熱壓行為~Post-bond capillary fill differs from preapplied-film TCB')], '在平行板、牛頓流體且忽略重力的教學尺度模型中 L²∝hγcosθ·t/μ；流長加倍需約四倍時間，黏度加倍需約兩倍時間。真實凸塊和填料會改變此關係。~For a Newtonian liquid between parallel plates, neglecting gravity, L²∝hγcosθ·t/μ: doubling length takes about four times as long and doubling viscosity twice as long. Bumps and fillers modify the relation.', '''
間隙幾何~Gap geometry|局部間隙和凸塊障礙控制流動阻力。~Local gaps and bump obstacles control flow resistance.|畫最窄通道及流動分岔。~Map narrowest channels and flow splits.|平均間隙足以預測所有填充時間~Using mean gap to predict every fill time
接觸角與表面~Contact angle and surface|潤濕取決於實際表面污染和粗糙度。~Wetting depends on actual contamination and roughness.|以相同清潔歷程見證片量測。~Measure witnesses with matched cleaning history.|材料手冊接觸角適用所有表面~Applying handbook contact angles to every surface
黏度與時間~Viscosity and time|材料黏度可能隨溫度及固化時間改變。~Viscosity may change with temperature and cure time.|比較使用前後流變曲線。~Compare rheology before and during use.|一次室溫黏度可代表整段填膠~Using one room-temperature viscosity for the whole fill
毛細尺度模型~Capillary scaling|理想流長平方隨時間成長，幾何和流變改變時須重新檢查。~Ideal squared flow length grows with time; geometry/rheology changes require reassessment.|繪 L² 對 t 並檢查曲線偏離。~Plot L² against t and inspect departures.|流長加倍只需兩倍時間~Assuming twice the flow length takes twice the time
填料與篩分~Fillers and filtration|粒徑相對間隙過大會堵塞或造成局部濃度變化。~Large particles relative to gaps can clog or change local concentration.|比較入口出口及窄隙填料分布。~Compare filler distributions at inlet, outlet and constrictions.|總填料比例相同就不會有局部偏析~Assuming equal bulk filler fraction excludes segregation
流前沿相遇~Meeting fronts|兩個前沿合流可能圍困空氣，增加出膠點並不必然更快更完整。~Meeting fronts can trap air; extra dispense sites do not guarantee better filling.|畫前沿時間序列與排氣路徑。~Draw front time sequences and vent paths.|四邊同時出膠總比單邊更無空洞~Assuming four-sided dispensing always eliminates voids
焊點與通道~Joints and channels|陣列方向改變流阻與毛細旁路，流量不均可繞過密集區。~Array direction alters resistance and bypass paths; flow can skip dense regions.|比較沿列與斜向流動示意。~Compare row-aligned and diagonal flow.|看到遠端出膠即可證明中間已填滿~Using far-edge arrival as proof of complete internal fill
固化收縮~Cure shrinkage|固化增加模數並帶來收縮，拘束條件決定殘餘應力。~Cure increases modulus and introduces shrinkage; constraints set residual stress.|比較自由收縮與接合堆疊變形。~Compare free shrinkage and bonded-stack deformation.|固化收縮只會改體積不會改應力~Assuming cure shrinkage changes volume but not stress
Tg 與 CTE~Tg and CTE|玻璃轉移附近模數和膨脹行為改變，不能用單一常數跨全溫域。~Modulus and expansion change near glass transition; one constant may not span temperatures.|把材料曲線與使用溫度範圍疊合。~Overlay material curves and operating range.|Tg 越高便無條件越可靠~Assuming higher Tg is unconditionally more reliable
空洞量測~Void metrology|空洞位置和連通性常比總面積更能反映風險。~Void location/connectivity can matter more than total area.|配對聲學圖、截面和焊點位置。~Pair acoustic maps, sections and joint locations.|相同空洞面積必有相同可靠度~Equating equal void area with equal reliability
吸濕與界面~Moisture and interfaces|吸濕膨脹與黏著下降可能在後續熱歷程中顯現。~Hygroscopic expansion and adhesion loss may appear during later heating.|比較乾燥對照與受濕樣本。~Compare dry controls with conditioned samples.|初始黏著強度能代表受濕後狀態~Using initial adhesion for moisture-conditioned behavior
返修與驗收~Rework and acceptance|可返修性、熱導及機械保護之間有權衡。~Reworkability, thermal conduction and mechanical protection trade off.|按產品邊界列雙重驗收條件。~Define paired acceptance criteria for product boundaries.|填滿且固化即滿足所有封裝需求~Assuming filled and cured meets every package need
''')
add(115,'模封收縮、材料非線性與翹曲~Mold shrinkage, material nonlinearity and warpage','材料表徵~Material characterization|流動與固化~Flow and curing|翹曲耦合~Warpage coupling|可靠度放行~Reliability release','imecfan henkeltech', [('a114','共用填料、Tg 和固化應力推理~Shares filler, Tg and cure-stress reasoning','模封厚區與底膠微間隙的流動尺度不同~Bulk mold regions differ from underfill microgaps'),('a117','大面積面板放大翹曲和材料不均效應~Large panels magnify warp and material nonuniformity','面板形狀和夾持條件不能直接沿用晶圓~Panel geometry/supports cannot simply copy wafer conditions')], '假設自由材料 CTE 差 10 ppm/K、ΔT=100 K，失配應變為 0.001=0.1%。這不是封裝應力；要計算應力還需模數、泊松比、幾何、固化參考態及鬆弛。~A hypothetical CTE difference of 10 ppm/K over 100 K gives mismatch strain 0.001=0.1%. Stress also needs modulus, Poisson ratio, geometry, cure reference state and relaxation.', '''
材料組成~Material composition|樹脂、填料及界面決定流動與熱機性質。~Resin, fillers and interfaces determine flow and thermomechanics.|將材料批次連到實測曲線。~Link material lots to measured curves.|相同填料百分比必有相同模數~Equating filler percentage with modulus
Tg 分段模型~Piecewise Tg model|Tg 附近的 CTE 和模數變化影響冷卻曲率。~CTE/modulus changes near Tg affect cooling curvature.|以分段曲線取代單一室溫值。~Use piecewise curves instead of one room-temperature value.|室溫模數可代表整段固化~Using room-temperature modulus throughout curing
固化參考態~Cure reference state|應力自由態並不一定是最高加工溫度。~The stress-free state is not necessarily peak process temperature.|追蹤凝膠、收縮與拘束開始。~Track gelation, shrinkage and constraint onset.|最高溫度必是零應力參考~Assuming peak temperature is stress-free
流動前沿~Flow fronts|晶粒與高低台階改變前沿，可能留下焊線掃移或空洞。~Dies and steps alter fronts, causing wire sweep or voids.|把前沿圖與缺陷位置相連。~Relate front maps to defect positions.|充滿模具即表示內部無空洞~Equating a full mold with void-free interiors
填料偏析~Filler segregation|局部填料變化使 CTE 和模數不均。~Local filler variation makes CTE/modulus nonuniform.|沿流向和厚度比較截面。~Compare sections along flow and through thickness.|整批配方相同就不可能局部翹曲差~Assuming one formulation excludes local warp variation
固化收縮~Cure shrinkage|化學收縮與熱收縮可作用於不同時間段。~Chemical and thermal shrinkage occur over different intervals.|分離等溫固化與降溫變形。~Separate isothermal-cure and cooling deformation.|所有收縮都可用 CTE·ΔT 描述~Describing all shrinkage with CTE·ΔT
層合不對稱~Laminate asymmetry|材料和厚度不對稱形成彎矩，總厚度相同亦可不同曲率。~Material/thickness asymmetry forms bending moments even at equal total thickness.|比較上下對稱及偏置晶粒截面。~Compare symmetric and offset-die sections.|總厚度相同必有相同翹曲~Equating total thickness with warpage
溫度依賴翹曲~Temperature-dependent warp|室溫平坦不保證接合或回流溫度平坦。~Room-temperature flatness does not ensure hot flatness.|量同一支撐條件的升降溫曲線。~Measure heating/cooling curves with matched supports.|只需室溫翹曲驗收~Qualifying warpage at room temperature only
黏彈鬆弛~Viscoelastic relaxation|時間與溫度影響應力鬆弛，瞬間彈性模型有適用限。~Time and temperature govern relaxation; instantaneous elasticity has limits.|比較不同保溫時間的變形。~Compare deformation at different dwell durations.|相同終溫必有相同殘應力~Assuming equal final temperature gives equal residual stress
量測支撐~Measurement support|夾持會壓平樣品並改變所量形状。~Clamping can flatten samples and change measured shape.|記錄重力方向、支點和接觸力。~Record gravity orientation, supports and contact force.|夾持後平坦即證明自由狀態平坦~Inferring free flatness from clamped flatness
分層與吸濕~Delamination and moisture|水分、界面黏著及熱失配可共同引發分層。~Moisture, adhesion and thermal mismatch can jointly cause delamination.|配對受濕歷程、聲學圖和破面。~Pair moisture history, acoustic maps and fracture faces.|分層只能歸因於材料黏度~Attributing delamination only to viscosity
模型校準與交接~Model calibration and handoff|模型需用獨立條件驗證，擬合一條曲線不足以預測新堆疊。~Validate on independent conditions; fitting one curve cannot establish transferability.|保留一種厚度或溫度歷程作盲測。~Hold out a thickness or thermal history for validation.|擬合誤差小即證明所有物性正確~Treating low fit error as proof of correct material properties
''')
add(116,'重組晶圓、晶粒位移與 RDL 互連~Reconstituted wafers, die shift and RDL interconnect','架構選擇~Architecture selection|重組與模封~Reconstitution and molding|RDL 建構~RDL construction|封裝驗證~Package validation','imecfan asefan', [('a117','共享重組、模封與 RDL 的互動~Shares reconstitution, molding and RDL interactions','面板尺度、邊界和曝光拼接不同於圓晶圓~Panel scale, boundaries and stitching differ from round wafers'),('a118','晶粒位移和模封表面是 RDL 對位輸入~Die shift and mold surfaces are RDL alignment inputs','扇出整合還包括來料良品、支撐與板級可靠度~Fan-out additionally includes die screening, support and board reliability')], '假設重組後晶粒平移 4 μm，而 RDL 捕捉墊可允許 ±6 μm；留給曝光、熱變形與量測不確定度的合計餘量只剩 2 μm，不可把各站公差各自都設為 6 μm。~If illustrative die shift is 4 μm and the RDL capture allowance is ±6 μm, only 2 μm remains for exposure, thermal deformation and measurement uncertainty—not 6 μm at every station.', '''
Chip-first 與 chip-last~Chip-first and chip-last|先放晶粒或先做 RDL 改變對位、已知良品與返修節點。~Die-first versus RDL-first changes overlay, screening and rework points.|畫兩路徑的材料與測試交接。~Map material/test handoffs for both routes.|兩路徑只改步驟名稱不改風險~Treating the routes as renamed identical risks
扇出面積配置~Fan-out area allocation|晶粒外增加配線區同時改變封裝尺寸與機械邊界。~Extra routing beyond die edges changes package size and mechanics.|標出晶粒、RDL、焊球和保護區。~Mark die, RDL, balls and keep-outs.|扇出面積只影響 I/O 數~Assuming fan-out area affects only I/O count
良品與重組地圖~Good-die and reconstitution map|來源晶圓與重組位置需一對一可追溯。~Source wafer and reconstituted position need one-to-one traceability.|驗證翻轉、旋轉與批次映射。~Verify flip, rotation and lot mapping.|重組後只保留封裝編號即可~Keeping only final package IDs after reconstitution
載板與膠層~Carrier and adhesive|載板 CTE 和黏著改變模封後晶粒位移。~Carrier CTE and adhesion affect post-mold die shift.|比較模封前後逐顆位置。~Compare per-die positions before/after molding.|初始放置精準就不會後續位移~Assuming accurate initial placement prevents later shift
模封流動~Mold flow|流動載荷和固化收縮可能造成平移與旋轉。~Flow loading and cure shrinkage can translate/rotate dies.|依流向分組分析位移向量。~Group displacement vectors by flow direction.|位移是純平移不需量旋轉~Treating shift as translation only
重組翹曲~Reconstituted warpage|晶粒與模封材料分布形成非均勻剛性和曲率。~Die/mold distribution creates nonuniform stiffness and curvature.|比較熱態與室溫全片形狀。~Compare hot and room-temperature wafer shapes.|平均晶粒密度足以描述翹曲~Using mean die density to describe warpage
露墊與表面~Pad exposure and surface|露墊、台階與殘膠決定 RDL 接觸和覆蓋。~Pad exposure, steps and residue determine RDL contact/coverage.|配對露墊截面與接觸電阻。~Pair pad sections with contact resistance.|可見金屬即等於可可靠接線~Equating visible metal with reliable contact
自適應對位~Adaptive alignment|以實際晶粒位置調整圖形需保留線間距及過孔規則。~Adapting patterns to die locations must preserve spacing and via rules.|比較調整前後 DRC 與捕捉餘量。~Compare DRC and capture margin before/after adaptation.|對位修正可以無限制拉伸配線~Allowing unlimited routing stretch for alignment
跨材料 RDL~Cross-material RDL|銅線跨越矽與模封邊界時承受局部失配應變。~Cu lines crossing Si/mold boundaries experience local mismatch strain.|定位裂紋與晶粒邊緣的關係。~Locate cracks relative to die edges.|RDL 直流導通便不需熱循環~Skipping thermal cycling after RDL continuity passes
焊球與板連接~Balls and board connection|封裝翹曲、球高和板變形共同決定接觸。~Package warp, ball height and board deformation jointly determine contact.|做熱態共面性與接合截面比較。~Compare hot coplanarity and bond sections.|球徑一致即可保證全部焊點接觸~Using equal ball diameter to guarantee all joints contact
端到端測試~End-to-end tests|晶粒、RDL 與板接口需分層定位以免誤判良率來源。~Localize die, RDL and board interfaces separately to identify yield losses.|建立各測試結構和故障對照表。~Map test structures to failure classes.|封裝總失效率可直接當晶粒失效率~Equating package failure rate with die failure rate
良率與成本~Yield and cost|良率、可用面積和重組損失決定每良品成本。~Yield, usable area and reconstitution loss set cost per good package.|比較相同封裝功能下兩路徑成本。~Compare routes at equal package functionality.|每片加工費較低就一定更便宜~Equating lower wafer processing cost with lower unit cost
''')
add(117,'大面積均勻性、面板變形與拼接對位~Large-area uniformity, panel distortion and stitching','面板布局~Panel layout|重組與搬運~Reconstitution and handling|大面積圖形~Large-area patterning|良率與可靠度~Yield and reliability','asefan asepanel', [('a116','兩者共用模封、重組晶粒與 RDL~Both share molding, reconstitution and RDL','圓晶圓與矩形面板的利用率、角落應力和設備夾持不同~Round wafers and rectangular panels differ in utilization, corner stress and clamping'),('a127','大面積玻璃的平坦度、破裂和 TGV 整合可比較~Large glass flatness, fracture and TGV integration can be compared','玻璃核心是永久基材，面板扇出可採暫時載板~Glass cores are permanent substrates; fan-out panels may use temporary carriers')], '假設 500×500 mm 面板四邊各排除 10 mm，可用面積 480²=230400 mm²；20×20 mm 封裝忽略街道時最多 24²=576 個。加街道、測試區及良率後數量必降。~For an illustrative 500×500 mm panel with 10 mm excluded edges, usable area is 480²=230400 mm²; 20×20 mm packages fit at most 24²=576 before streets, test zones and yield.', '''
格式與設備邊界~Format and tool boundaries|面板尺寸須同曝光、鍍膜、搬運和檢測設備相容。~Panel size must fit patterning, deposition, handling and inspection.|建立所有站點有效處理面積表。~List effective process areas at every station.|單一設備可容納就代表整線可用~Equating one tool's capacity with line compatibility
邊緣與利用率~Edges and utilization|邊緣排除、街道和測試區降低幾何利用率。~Edge exclusions, streets and test zones reduce utilization.|用實際格點配置計數而非只除面積。~Count grid placements rather than divide area alone.|總面積除單位面積就是實際產量~Using area division as actual output
晶粒分布~Die distribution|不均勻晶粒密度使模封流動和剛性有方向性。~Uneven die density makes mold flow and stiffness directional.|比較中央、邊緣與角落配置。~Compare central, edge and corner layouts.|相同平均密度即可消除局部差異~Assuming equal mean density removes local differences
搬運撓曲~Handling sag|大跨距使重力撓曲增加，取放時形狀不同於量測平台。~Large spans increase sag; handling shape differs from metrology support.|畫吸盤間距與懸空區。~Draw suction spacing and unsupported spans.|量測時平坦即可證明搬運不彎曲~Using flat metrology to prove no handling sag
熱變形場~Thermal distortion field|長尺度下小 CTE 差亦造成顯著非剛體位移。~Small CTE differences create substantial nonrigid displacement over large scales.|擬合平移旋轉後再看殘差場。~Fit rigid motion, then inspect residual fields.|一個全域平移可修正全部熱變形~Correcting all thermal distortion with one translation
模封角落~Mold corners|矩形角落的流動和應力邊界不同於中央。~Rectangular corners have different flow/stress boundaries from centers.|單獨統計四角空洞和翹曲。~Track corner voids and warpage separately.|只採樣中心即可代表面板~Sampling only the center to represent a panel
曝光拼接~Exposure stitching|曝光場接縫需控制位置、尺度和線段連續性。~Field seams need position, scale and conductor continuity control.|跨接縫設計線阻與套刻見證。~Use resistance and overlay witnesses across seams.|每場內 DRC 通過便無拼接問題~Assuming within-field DRC excludes stitching defects
RDL 厚度均勻~RDL thickness uniformity|鍍液流場和電流分配在大面積可能不均。~Flow and current distribution can be nonuniform over large areas.|繪厚度地圖並按電流路徑分組。~Map thickness and group by current paths.|平均鍍厚符合即可忽略邊緣薄區~Ignoring thin edges after mean thickness passes
圖形伸縮補償~Pattern-scale compensation|尺寸補償須保留局部設計規則及連接捕捉餘量。~Scale compensation must preserve local rules and capture margin.|檢查補償前後線距與過孔重疊。~Check spacing and via overlap after compensation.|縮放全圖不會改變電性規則~Assuming global scaling never changes electrical rules
分割與殘應力~Singulation and residual stress|分割釋放面板應力，單顆封裝形狀可能改變。~Singulation releases panel stress and can change package shape.|比較分割前後曲率與接點電性。~Compare curvature/electrical data before and after singulation.|面板翹曲合格就保證單顆翹曲合格~Inferring package warpage from panel warpage
空間良率~Spatial yield|邊緣群聚失效代表系統機制，不宜只報全板平均。~Edge-clustered failures indicate systematic mechanisms hidden by averages.|建立位置、站點與失效類型交叉圖。~Cross-map position, station and failure class.|相同總良率代表同樣成熟度~Equating equal total yield with equal process maturity
規模化經濟~Scale economics|面積增加需扣除設備、搬運損失和修補成本。~Larger area must account for tool, handling and rework costs.|比較每良品成本及尾端風險。~Compare cost per good unit and tail risks.|面板越大成本必單調下降~Assuming larger panels always lower unit cost
''')
add(118,'細線 RDL、過孔連通與跨材料可靠度~Fine RDL, via continuity and cross-material reliability','介面與版圖~Interfaces and layout|微影與種子~Lithography and seed|電鍍與蝕除~Plating and etchback|電性與壽命~Electrical and lifetime','atotech atotechrdl imecpdk', [('a103','共用圖形電鍍、種子與電流分配~Shares patterned plating, seed and current distribution','RDL 關心橫向細線及彎折，銅柱關心高寬與共面性~RDL emphasizes thin lateral traces/bends; pillars emphasize aspect and coplanarity'),('a116','重組面的位置和材料邊界是 RDL 條件~Reconstituted location and material boundaries constrain RDL','RDL 可用於多種基材而不僅扇出封裝~RDL applies to many substrates beyond fan-out')], '假設銅線 L=2 mm、w=5 μm、t=3 μm、ρ=1.7×10⁻⁸ Ω·m，R≈2.27 Ω。若線寬減少 10% 而其餘不變，R 增加約 11.1%；不含接點與尺寸效應。~For L=2 mm, w=5 μm, t=3 μm and ρ=1.7×10⁻⁸ Ω·m, R≈2.27 Ω. A 10% width reduction raises R by about 11.1%, excluding contacts and size effects.', '''
互連功能分層~Interconnect function layers|電源與訊號線有不同寬度、阻抗和電流需求。~Power and signal traces need different widths, impedances and currents.|標每層網路及回流面。~Mark networks and return planes per layer.|最小線寬可用於所有電源線~Using minimum width for all power traces
介電層與固化~Dielectric and cure|介電層的厚度、吸濕和固化影響電容與附著。~Thickness, moisture and cure affect capacitance and adhesion.|配對厚度、漏電及剝離見證。~Pair thickness, leakage and adhesion witnesses.|介電層只需看擊穿電壓~Assessing dielectric only by breakdown voltage
過孔開口~Via openings|底部殘留和側壁形狀決定金屬連通。~Bottom residue and wall profile determine metal continuity.|比較頂部尺寸與孔底截面。~Compare top dimensions with bottom sections.|頂視過孔打開即底部必潔淨~Assuming a visible opening has a clean bottom
種子覆蓋~Seed coverage|台階和孔壁需連續導電層才能均勻成長。~Steps and via walls need continuous seed for uniform growth.|以片阻加截面檢查覆蓋。~Use sheet resistance plus coverage sections.|平面厚度足夠即可證明孔壁覆蓋~Using planar thickness to prove sidewall coverage
光阻解析~Resist resolution|線寬、厚度和側壁角共同限制細線成形。~Width, thickness and wall angle jointly limit trace formation.|在密集與孤立線測底寬。~Measure bottom widths in dense/isolated lines.|頂部線寬可代表整個截面~Using top width for the whole cross-section
對位捕捉~Overlay capture|過孔与下層墊的重疊須包含製程偏移和量測誤差。~Via-pad overlap must include process and metrology errors.|將重疊面積地圖和開路相配。~Correlate overlap-area maps and opens.|中心偏差合格就必有足夠邊界~Assuming acceptable center error guarantees edge margin
電鍍線形~Plated profile|電流擁擠可使線頂與邊緣過厚，平均厚度不能代表最窄截面。~Crowding can overplate tops/edges; mean thickness hides constrictions.|量線頂、底及彎角截面。~Measure top, bottom and bend sections.|電鍍總量可直接推得最小線截面~Inferring minimum cross-section from total plated mass
雜質與延展~Impurities and ductility|細銅線的微結構影響裂紋敏感性，需驗證實際沉積材料。~Fine-Cu microstructure affects crack sensitivity; validate actual deposits.|比較退火前後晶粒與拉伸見證。~Compare grains and tensile witnesses before/after anneal.|所有銅沉積都可用塊材延展性~Using bulk ductility for every deposited Cu film
去種子側蝕~Seed-etch undercut|清除種子防短路時會縮小細線根部。~Seed removal prevents shorts but can narrow trace roots.|同時量絕緣與根部線寬。~Measure isolation and root width together.|絕緣通過便可忽略線根變窄~Ignoring root narrowing after isolation passes
電阻與尺寸~Resistance and dimensions|電阻受截面最小值與接點影響，不只設計線寬。~Resistance depends on constrictions and contacts, not just design width.|以四端線阻配合截面重建。~Combine four-terminal trace resistance and sections.|名義線寬即可準確計算全線阻值~Calculating exact resistance from nominal width alone
跨界面應變~Cross-interface strain|RDL 跨越不同 CTE 材料時局部應变較高。~RDL crossing dissimilar-CTE materials can have elevated local strain.|按晶粒邊界和彎角定位裂紋。~Locate cracks by die boundaries and bends.|直線區無裂紋即可忽略跨界面段~Ignoring interface crossings after straight traces pass
可靠度與設計回饋~Reliability and design feedback|線距、過孔冗餘和熱循環資料需回饋設計規則。~Spacing, via redundancy and cycling results must inform design rules.|建立失效位置對版圖規則的對照。~Map failures back to layout rules.|一次電測合格即可凍結所有設計規則~Freezing all rules after one electrical pass
''')
add(119,'嵌入深度、雷射接點與層合可靠度~Embedding depth, laser contacts and laminate reliability','嵌入架構~Embedding architecture|放置與層合~Placement and lamination|接點形成~Contact formation|驗證與熱路徑~Verification and thermal paths','asevip atotechmulti', [('a120','共用異質元件分工與系統測試~Shares heterogeneous partitioning and system testing','嵌入晶粒更難返修且受層壓材料拘束~Embedded dies are less reworkable and constrained by laminate'),('a128','共用增層介電質、微孔及銅金屬化~Shares build-up dielectric, microvias and Cu metallization','嵌入架構還需處理晶粒台階與元件保護~Embedding additionally handles die steps and device protection')], '假設晶粒厚 100±5 μm、腔深 120±4 μm，名義上方餘隙 20 μm；若公差為界限，最小餘隙 11 μm、最大 29 μm。RSS 只適用已知統計模型，不能替代最壞界限。~For a 100±5 μm die in a 120±4 μm cavity, nominal clearance is 20 μm and bounded extremes are 11–29 μm. RSS requires a statistical model and cannot replace worst-case bounds.', '''
腔體與層疊~Cavity and stackup|腔深與晶粒厚度決定上方介電質及平坦度。~Cavity depth and die thickness set cover dielectric and flatness.|列最壞組合的幾何界限。~List worst-case geometry combinations.|名義腔深較大就不需公差分析~Skipping tolerances when nominal cavity depth is larger
晶粒良品~Known-good embedded die|嵌入後返修受限，前測覆蓋影響整板成本。~Limited rework makes pretest coverage important to board cost.|比較前測投入與報廢層板風險。~Compare screening effort and laminate scrap risk.|嵌入前測試可全由終測取代~Replacing pre-embedding tests with final tests
焊墊金屬相容~Pad metallurgy|晶粒墊需承受後續雷射開孔及金屬化。~Die pads must tolerate laser opening and metallization.|畫焊墊厚度與保護層剖面。~Draw pad thickness and protection sections.|任何原晶粒墊都可直接雷射連接~Laser-contacting any original die pad unchanged
固定與位移~Fixation and shift|層壓流動和壓力會讓晶粒平移或傾斜。~Lamination flow/pressure can shift or tilt dies.|比對層壓前後 fiducial 位置。~Compare fiducials before/after lamination.|放置精度就是最終嵌入精度~Equating placement with final embedding accuracy
樹脂填充~Resin filling|晶粒周圍狹縫可能形成樹脂不足與氣泡。~Narrow die-edge gaps can cause resin starvation and voids.|取晶粒角落和中央截面。~Section corners and centers.|板表面平整即內部無空洞~Inferring no internal voids from a flat board
層壓應力~Lamination stress|不均勻壓力可能使晶粒彎曲，總壓力不能代表局部負載。~Uneven pressure can bend dies; total pressure hides local loads.|連結支撐、腔體與破裂位置。~Relate support, cavities and fracture sites.|降低總壓力必能解決所有破片~Assuming lower pressure solves every fracture
開孔對位~Via-to-pad alignment|埋藏焊墊的位置需從可見標記和層壓變形推定。~Buried pad locations depend on visible references and laminate distortion.|保留局部對位殘差與捕捉邊界。~Retain local residuals and capture boundaries.|外框標記對準即可保證所有埋藏墊~Using frame alignment to guarantee every buried pad
孔底損傷~Via-bottom damage|開孔需露出焊墊又避免薄墊受損。~Opening must expose pads without damaging thin metal.|比較孔底截面和接觸電阻。~Compare bottom sections and contact resistance.|孔開得越深連接必越可靠~Assuming deeper openings always improve contact
金屬化連續~Metallization continuity|孔壁與焊墊的連續覆蓋決定垂直接點。~Continuous wall-to-pad coverage determines vertical connection.|用鏈路加局部截面定位不連續。~Use chains and local sections to locate discontinuity.|表面銅厚足夠即可保證孔底連通~Using surface Cu thickness to prove bottom contact
熱流路徑~Thermal paths|嵌入介電質可能增加熱阻，電路縮短不代表散熱改善。~Embedding dielectric may increase thermal resistance despite shorter electrical paths.|比較晶粒到板面與銅平面的熱網路。~Compare thermal networks to board surfaces and Cu planes.|互連短就必定結溫較低~Assuming shorter interconnect guarantees lower junction temperature
水分與界面~Moisture and interfaces|晶粒—樹脂界面可能成為吸濕分層路徑。~Die–resin interfaces can become moisture-delamination paths.|對照受濕後聲學與電性。~Compare conditioned acoustic/electrical results.|層壓後密封就不再吸濕~Assuming lamination prevents all moisture uptake
測試與失效拆解~Testing and failure analysis|埋藏元件需要設計測試節點及保留非破壞證據。~Buried components need test access and retained nondestructive evidence.|先定位網路再決定破壞性截面。~Localize nets before destructive sectioning.|看到內部需要先研磨整板~Grinding the board before localization
''')
add(120,'功能分割、異質接口與系統驗證~Functional partitioning, heterogeneous interfaces and system validation','系統分工~System partition|封裝架構~Package architecture|跨域整合~Cross-domain integration|測試與供應鏈~Test and supply chain','asesip asevip', [('a119','皆需將材料接口和功能测试共同設計~Both co-design material interfaces and functional tests','SiP 可採多種放置方式，嵌入晶粒是其中一種~SiP supports many assembly forms; embedding is one'),('a191','電、熱與光接口使跨域預算更重要~Electrical, thermal and optical interfaces intensify cross-domain budgets','CPO 另外需要光耦合、光源與雷射安全~CPO additionally needs coupling, sources and laser safety')], '假設三子模組獨立良率 0.98、0.99、0.97，且組裝良率 0.95，粗估總良率乘積≈0.894。此模型不含相關缺陷、返修與篩選，可作比較基準而非產量承諾。~Illustrative independent module yields 0.98, 0.99, 0.97 and assembly yield 0.95 multiply to≈0.894, excluding correlations, rework and screening.', '''
功能需求樹~Functional requirement tree|系統性能需拆成可量測的模組接口。~System performance must become measurable module interfaces.|把頻寬、延遲、功耗連到各元件。~Allocate bandwidth, latency and power to components.|把功能元件放一起即成完整系統~Equating colocated components with a complete system
晶粒技術分工~Die technology partition|不同製程的優勢須抵銷封裝接口成本。~Process-node benefits must offset packaging-interface costs.|比較單晶片與多晶粒的完整預算。~Compare complete monolithic and multichip budgets.|分割越多一定越省成本~Assuming more partitioning always lowers cost
接口契約~Interface contracts|電壓、時序、阻抗、協定和測試要求都需一致。~Voltage, timing, impedance, protocol and test contracts must agree.|列雙方責任和版本。~List ownership and versions.|協定名稱相同即保證互通~Equating a shared protocol name with interoperability
封裝拓撲~Package topology|2D、2.5D、3D 改變連線長度、散熱及可測性。~2D/2.5D/3D change links, cooling and testability.|畫三種拓撲的電熱路徑。~Draw electrical/thermal paths for each topology.|最短連線總是最好的架構~Assuming shortest links always give the best architecture
被動元件配置~Passive placement|去耦、濾波和匹配元件需按回路而非空位配置。~Place decoupling/filtering/matching components by loops, not free space.|標出電源與射頻電流閉合路徑。~Mark closed power and RF current loops.|電容越靠近外觀上的晶粒中心越好~Placing capacitors by visual proximity to die center
熱源共存~Coexisting heat sources|高功耗元件會升高鄰近敏感元件溫度。~High-power components warm sensitive neighbors.|比較局部熱源開關的交叉溫升。~Compare cross-heating with individual sources toggled.|各元件單獨熱測通過即可~Relying only on individual thermal passes
射頻隔離~RF isolation|共用電源、地和基材都可能耦合干擾。~Shared power, grounds and substrates can couple interference.|畫有意信號與非預期耦合路徑。~Draw desired signals and unintended coupling.|金屬罩能消除全部電源耦合~Assuming a shield eliminates all power coupling
機械堆疊~Mechanical stackup|材料失配和元件高度決定局部應力及共面性。~Material mismatch and component height set stress/coplanarity.|比較關鍵界面的熱機邊界。~Compare thermomechanical boundaries at key interfaces.|元件全固定好就不需應力分析~Skipping stress analysis after mechanical fixation
測試可觀測性~Test observability|每項功能需可控制輸入和可觀察輸出。~Each function needs controllable inputs and observable outputs.|把測試點對照失效類型。~Map test points to failures.|系統啟動成功等於全部接口合格~Equating successful boot with all interface qualification
良率與返修~Yield and rework|昂貴模組的組装順序會影響報廢成本。~Assembly order of expensive modules changes scrap cost.|比較早測、晚測及可返修分支。~Compare early tests, late tests and rework branches.|只看最終良率就能比較生產成本~Comparing manufacturing cost from final yield alone
版本與來源~Versions and provenance|晶粒、基板和韌體版本須一起追溯。~Die, substrate and firmware versions need joint traceability.|建立可重現的 BOM 和接口版本表。~Build reproducible BOM and interface version tables.|韌體升級不會影響封裝驗證~Assuming firmware changes never affect package qualification
系統接受測試~System acceptance|電、熱、機械及軟體證據需對應同一工作負載。~Electrical, thermal, mechanical and software evidence must share a workload.|提交代表和邊界情境驗證矩陣。~Submit representative and boundary-scenario matrices.|各領域各自最佳即保證系統最佳~Assuming independently optimized domains guarantee the best system
''')
add(121,'TSV 孔形、絕緣覆蓋與漏電~TSV geometry, insulation coverage and leakage','孔洞架構~Via architecture|深矽蝕刻~Deep silicon etch|絕緣界面~Insulating interfaces|測試交接~Test handoff','oxdrie imec3d', [('a122','孔形與絕緣連續性決定後續金屬填充~Geometry and insulation continuity constrain metal filling','本課處理孔與介電質，填充課處理種子、成長和空洞~This course treats holes/dielectrics; filling treats seed/growth/voids'),('a112','深蝕刻負載、側壁與終點方法可比較~Deep-etch loading, sidewalls and endpoint methods transfer','TSV 多為盲孔，切割通常要求穿透至載膜~TSVs are often blind; dicing breaks through to tape')], '假設孔深 50 μm、直徑 5 μm，深寬比 10。理想同軸近似 C≈2π εL/ln(b/a)，a 為導體半徑、b 為外側半徑；真正 TSV 還含半導體耗盡與頻率依賴。~A 50 μm deep, 5 μm diameter illustrative via has aspect ratio 10. Ideal coaxial C≈2π εL/ln(b/a), with conductor radius a and outer radius b; real TSVs add semiconductor depletion and frequency dependence.', '''
Via-first/middle/last~Via-first/middle/last|形成時點決定可用熱預算與保護的既有結構。~Insertion timing determines thermal budget and structures needing protection.|畫三條整合路徑和不可逆界面。~Draw three integration routes and irreversible interfaces.|所有 TSV 都可用相同熱預算~Giving every TSV the same thermal budget
孔徑與深度~Diameter and depth|深寬比影響傳輸、側壁覆蓋和後續填充。~Aspect ratio affects transport, coating and filling.|量上中下直徑而非只量入口。~Measure top/middle/bottom diameter.|入口孔徑足以描述整個 TSV~Describing a TSV only by its entrance diameter
遮罩與保護區~Mask and keep-outs|遮罩要承受深蝕刻且保護附近元件。~Masks must survive deep etch while protecting nearby devices.|估最壞遮罩消耗和對位界限。~Estimate worst mask loss and overlay bounds.|孔位對準就可忽略遮罩退縮~Ignoring mask retreat after alignment passes
深度負載~Depth loading|孔密度與深寬比使不同區域蝕刻速率不同。~Via density and aspect ratio cause spatial etch-rate differences.|按孔群密度比較深度圖。~Compare depth maps by via density.|固定時間可保證每孔同深~Assuming fixed time ensures equal depth
側壁紋路~Sidewall scallops|週期紋路增加有效表面和局部電場集中。~Cyclic scallops increase surface area and field concentration.|將紋路幅度同後續覆蓋截面對照。~Compare scallop amplitude with coating sections.|平均側壁角垂直即絕緣必均勻~Assuming vertical mean angle ensures uniform insulation
孔底與轉角~Bottom and corners|孔底轉角影響沉積連續與局部場強。~Bottom corners affect coating continuity and local fields.|檢查最薄絕緣處而非平均厚度。~Inspect thinnest insulation, not the mean.|平均膜厚可排除所有擊穿弱點~Using average thickness to exclude breakdown weak spots
清潔與表面~Cleaning and surface|蝕刻殘留與表面損傷改變介電質界面。~Etch residue and damage change dielectric interfaces.|配對清潔見證與漏電分布。~Pair cleaning witnesses and leakage distributions.|孔洞幾何合格即不需表面驗證~Skipping surface qualification after geometry passes
絕緣覆蓋~Insulation coverage|共形膜在深孔仍可能有厚度與材料品質梯度。~Conformal films can still vary in thickness/quality down deep vias.|截面取孔頂、中、底並驗證電性。~Sample top/middle/bottom and verify electrically.|共形沉積名稱即保證全孔相同性質~Treating a conformal-process label as proof of uniform properties
漏電與擊穿~Leakage and breakdown|漏電、擊穿及時間退化是不同測量。~Leakage, breakdown and time-dependent degradation are distinct.|規劃電壓、溫度及時間的分離見證。~Plan separate voltage, temperature and time witnesses.|低初始漏電即可預測無限壽命~Inferring unlimited life from low initial leakage
電容與基板~Capacitance and substrate|TSV—矽系統可能具有偏壓和頻率依賴。~TSV–silicon behavior may depend on bias and frequency.|比較 C–V、頻率與基板電阻率。~Compare C–V, frequency and substrate resistivity.|TSV 電容永遠是固定平行板值~Treating TSV capacitance as a fixed parallel-plate value
應力保護區~Stress keep-out zone|填銅後熱失配可影響周邊元件，孔洞設計須提前保留區。~Post-fill mismatch can affect nearby devices; reserve space early.|比較鄰近與遠端見證元件。~Compare nearby and remote witness devices.|孔外絕緣良好即可取消應力保護區~Removing stress keep-outs after insulation passes
金屬化交接~Metallization handoff|填充需要可覆蓋孔形、潔淨表面及已驗證絕緣。~Filling requires coatable geometry, clean surfaces and qualified insulation.|提交孔形與漏電共同地圖。~Deliver paired geometry/leakage maps.|孔深達標即表示可直接填銅~Assuming target depth alone makes vias ready for Cu
''','a025')
add(122,'阻障種子、成長前沿與空洞~Barrier/seed, growth fronts and voids','材料與孔形~Materials and geometry|阻障與種子~Barrier and seed|金屬填充~Metal filling|應力與電性~Stress and electrical','atotech atotechmulti', [('a121','孔壁形貌與絕緣是填充輸入~Sidewall geometry and insulation are filling inputs','本課重點為導體完整、接觸和金屬熱應力~This course emphasizes conductor continuity, contact and metal stress'),('a123','填充後突出與空洞位置影響背面露出~Post-fill protrusion and void locations affect backside reveal','填充須形成導體，露出須保留導體與絕緣~Filling forms conductors; reveal preserves conductors and insulation')], '假設直徑 5 μm、長 50 μm 的理想銅 TSV，ρ=1.7×10⁻⁸ Ω·m，R≈43.3 mΩ。截面有效面積若因空洞減少 20%，均勻模型 R 增至約54.1 mΩ；真實空洞還有電流集中。~An ideal 5 μm diameter, 50 μm long Cu TSV at ρ=1.7×10⁻⁸ Ω·m has R≈43.3 mΩ. A uniform 20% area loss gives≈54.1 mΩ, before real void current crowding.', '''
導體選擇~Conductor selection|Cu 與 W 的電阻、成膜方式和热失配不同。~Cu and W differ in resistivity, deposition and thermal mismatch.|比較電阻與應力的雙目標表。~Compare resistance and stress objectives.|最低電阻材料必是每種 TSV 最佳選擇~Assuming lowest resistivity is always best
孔形來料~Incoming geometry|再入形孔口可能先封閉而困住內部空洞。~Reentrant mouths can close early and trap voids.|量孔口收縮及全深度截面。~Measure mouth constriction and full-depth profile.|孔口越窄越容易無空洞填滿~Assuming narrower mouths facilitate void-free fill
擴散阻障~Diffusion barrier|阻障需阻擋金屬進入介電質或矽，同時維持接觸。~Barriers must block metal diffusion while preserving contact.|比較連續性、厚度和接觸電阻。~Compare continuity, thickness and resistance.|阻障越厚越能無代價提高可靠度~Assuming thicker barriers improve reliability without cost
種子連通~Seed connectivity|深孔種子不連續會使局部無法電鍍。~Discontinuous deep seed prevents local plating.|將片阻和孔底截面合併判讀。~Combine sheet resistance and bottom sections.|表面種子導通即孔底也連通~Inferring bottom continuity from surface conductivity
潤濕與氣泡~Wetting and bubbles|被困氣體阻斷局部沉積，與後期封口空洞有不同位置特徵。~Trapped gas blocks deposition and differs from late pinch-off voids.|比較空洞形狀和分布高度。~Compare void shape and height distribution.|所有空洞都由電鍍電流過小造成~Attributing every void to low plating current
底部優先成長~Bottom-up growth|填充前沿需要避免上部提前封口，局部成長速度是關鍵。~Growth fronts must avoid early mouth closure; local rates matter.|重建多個中間截面的前沿演化。~Reconstruct fronts from intermediate sections.|總沉積量相同即可保證相同填充形貌~Equating total deposited mass with fill morphology
傳質與圖形~Transport and pattern|孔密度、流場和深度影響有效反應物供應。~Density, flow and depth affect reactant supply.|按密度區比較空洞與厚度。~Compare voids/thickness by density region.|流場均勻就代表所有孔內傳質相同~Equating uniform bulk flow with equal in-via transport
過鍍與平坦化~Overburden and planarization|表面金屬留量須足夠平坦化又限制應力與材料耗損。~Overburden must enable planarization while limiting stress/waste.|列去除量、凹陷和殘留預算。~Budget removal, dishing and residue.|表面越厚越容易且無風險平坦化~Assuming thicker overburden makes planarization risk-free
熱處理與突出~Thermal treatment and protrusion|金屬微結構和 CTE 失配可使 TSV 突出或應力重分布。~Microstructure and CTE mismatch can cause protrusion or stress redistribution.|量熱前後高度與周邊應變。~Measure pre/post-thermal height and nearby strain.|銅填滿後幾何永遠固定~Assuming filled Cu geometry never changes
四端電測~Four-terminal testing|實測電阻包含端點與有效截面，低阻並不排除小空洞。~Resistance includes terminations/area; low resistance does not exclude small voids.|將 Kelvin 結果和非破壞影像對照。~Compare Kelvin results and nondestructive images.|低電阻即可免除空洞檢測~Skipping void inspection after low resistance
熱機耦合~Thermomechanical coupling|局部空洞和剛性梯度使應力集中。~Voids and stiffness gradients concentrate stress.|對照裂紋、空洞及熱循環位置。~Correlate cracks, voids and cycling locations.|空洞只影響電阻不影響機械性~Assuming voids affect resistance but not mechanics
放行與露出~Release to reveal|填充驗收需包含孔口、孔底及將被露出的區域。~Qualify mouth, bottom and future reveal region.|交付深度對位圖與缺陷界限。~Deliver depth-registered maps and defect bounds.|只截孔中部即可代表露出端品質~Using only mid-via sections to qualify reveal ends
''','a025')
add(123,'薄化終點、選擇比與露出均勻性~Thinning endpoint, selectivity and reveal uniformity','深度與支撐~Depth and support|接近 TSV~Approach TSVs|選擇性露出~Selective reveal|背面連接~Backside connection','disco imecback', [('a110','粗薄化的 TTV 和損傷決定露出起始範圍~Grinding TTV/damage determine the reveal starting range','露出額外需要區分矽、絕緣和金屬終點~Reveal additionally distinguishes Si, dielectric and metal endpoints'),('a122','金屬填充完整性和突出會在露出時顯現~Fill integrity and protrusion emerge during reveal','填充孔底缺陷不能靠露出自動修復~Reveal does not automatically repair bottom fill defects')], '假設最深未露出 TSV 上方還有 3 μm 矽，最快區已露出；若理想矽對保護層選擇比 30，額外移除 3 μm 矽對應 0.1 μm 保護層消耗，仍須另加非均勻與量測餘量。~If the latest TSV has 3 μm Si remaining while another is exposed, ideal selectivity 30 implies 0.1 μm protective-layer loss during completion, before nonuniformity and metrology margins.', '''
深度座標~Depth coordinates|TSV 深度與背面厚度必須共用原始正面基準。~TSV depth and backside thickness need a common frontside datum.|統一圖面和量測零點。~Unify design and metrology zero references.|兩個深度數值相減不需檢查基準~Subtracting depths without checking datums
來料 TTV~Incoming TTV|全片厚度分布決定最早和最晚露出區。~Thickness distribution determines earliest/latest reveal sites.|將 TTV 與 TSV 深度地圖配準。~Register TTV and via-depth maps.|平均厚度達標即所有 TSV 同步露出~Equating mean thickness with simultaneous reveal
載板支撐~Carrier support|背面加工載荷需由前側支撐承受且避免位移。~Frontside support carries backside loads without shift.|檢查膠層空洞及前後位移。~Inspect adhesive voids and displacement.|載板剛性高即可忽略膠層~Ignoring adhesive because the carrier is stiff
研磨接近~Grinding approach|大量移除應在碰到敏感金屬前保留可控餘量。~Bulk removal needs controllable allowance before sensitive metal.|建立最壞厚度與停止界限。~Define worst thickness and stop boundaries.|只依固定研磨時間就可安全到 TSV~Reaching TSVs safely by fixed grinding time alone
損傷層去除~Damage removal|背面損傷影響後續蝕刻均勻與機械強度。~Backside damage affects etch uniformity and strength.|比较損傷深度與剩餘留量。~Compare damage depth and remaining allowance.|露出金屬後損傷自然不重要~Assuming damage ceases to matter after metal exposure
選擇比~Selectivity|矽、介電質和金屬的相對移除速率決定窗口。~Relative Si/dielectric/metal removal rates define the window.|以見證層量實際選擇比。~Measure selectivity on witness layers.|高矽蝕刻速率就是高選擇比~Equating fast Si removal with high selectivity
終點感測~Endpoint sensing|全域訊號可能先反映大面積區而非最晚孔。~Global signals may reflect large regions rather than last vias.|以局部量測核對全域終點。~Check global endpoints against local measurements.|全域終點一出現即可停止且全部完成~Stopping at first global endpoint as complete reveal
突出高度~Protrusion height|露出高度分布影響後續介電質覆蓋與接觸。~Protrusion distribution affects later dielectric coverage/contact.|量每區高度與支撐面相對關係。~Measure regional height relative to support planes.|平均突出高度可代表所有接點~Using mean protrusion for every contact
絕緣保存~Insulation preservation|側壁絕緣在露出時仍需隔離金屬與矽。~Sidewall insulation must retain metal–Si isolation during reveal.|對照漏電與露出端截面。~Compare leakage and revealed-end sections.|金屬露出後不再需要側壁絕緣~Assuming exposed metal no longer needs sidewall insulation
污染與氧化~Contamination and oxidation|暴露金屬可能再氧化或受殘留污染。~Exposed metal can oxidize or retain residue.|把等待歷程與接觸電阻配對。~Pair queue history and contact resistance.|露出形貌良好就一定可低阻接觸~Inferring low-resistance contact from good shape
背面 RDL~Backside RDL|新配線需捕捉實際 TSV 位置和高度。~Backside routing must capture actual TSV position/height.|核對背面坐標鏡像及焊墊重疊。~Check backside mirroring and pad overlap.|正面座標可不轉換直接使用背面~Using frontside coordinates unchanged on the back
露出驗收~Reveal acceptance|露出完整、低漏電和良好接觸需三重證據。~Complete reveal, low leakage and good contact need separate evidence.|建立逐區幾何電性對照。~Build regional geometry/electrical comparisons.|看到每個 TSV 即代表露出合格~Qualifying reveal solely because every TSV is visible
''','a025')
add(124,'玻璃孔洞、裂紋與金屬化~Glass vias, cracking and metallization','玻璃與孔設計~Glass and via design|成孔與邊緣~Hole formation and edges|金屬化~Metallization|電熱機驗證~Multiphysics validation','corningtgv atotechmulti', [('a121','深孔幾何和覆蓋的量測方法可共用~Geometry/coverage metrology transfers','玻璃是絕緣脆材，矽 TSV 有半導體基板與額外絕緣界面~Glass is brittle/insulating; Si TSVs include semiconductor substrates and insulation'),('a127','TGV 是玻璃核心垂直互連的重要單元~TGVs are key glass-core vertical interconnects','TGV 局部合格尚不足以驗證完整多層基板~Local TGV qualification does not qualify a multilayer substrate')], '假設玻璃厚 300 μm、孔徑 50 μm，深寬比 6；若金屬只鍍成 5 μm 厚圓筒，導體面積 π(25²−20²)≈707 μm²，不可用實心孔面積 1963 μm² 計算電阻。~For 300 μm glass and 50 μm vias, aspect ratio is 6. A 5 μm plated shell has area π(25²−20²)≈707 μm², not the 1963 μm² area of a solid via.', '''
玻璃組成~Glass composition|玻璃的 CTE、介電損耗和強度依組成及加工而異。~CTE, dielectric loss and strength depend on composition/processing.|指定材料牌號和量測頻率。~Specify material grade and measurement frequency.|所有玻璃具有相同介電與熱性質~Treating all glass as one material
通孔與盲孔~Through and blind vias|孔類型決定成孔、金屬化及排氣路徑。~Via type changes drilling, metallization and venting.|畫孔口、孔底和對外連通。~Draw mouths, bottoms and vent connections.|盲孔可直接沿用通孔的填充假設~Using through-via fill assumptions for blind vias
孔形與錐度~Profile and taper|錐度改變金屬覆蓋和局部電流面積。~Taper changes coating and current-carrying area.|量上下直徑和壁面粗糙度。~Measure both diameters and wall roughness.|入口直徑就是最小導體截面~Treating entrance diameter as minimum conducting area
成孔裂紋~Hole-formation cracks|脆性玻璃的微裂紋可能在熱循環後成長。~Glass microcracks may grow during thermal cycling.|比較成孔前後偏光與截面證據。~Compare polariscopic/section evidence before and after drilling.|孔可導通就可忽略玻璃微裂紋~Ignoring glass microcracks after via continuity passes
孔間距與強度~Pitch and strength|孔群降低承載截面，邊距和排列影響破裂。~Via arrays reduce load-bearing area; edge distances/layout matter.|比較單孔和密集陣列見證片。~Compare isolated-hole and dense-array witnesses.|單孔強度足以代表所有孔陣列~Using single-hole strength for all arrays
表面附著~Surface adhesion|玻璃—金屬附著需驗證，低粗糙表面不自動等於高黏著。~Glass–metal adhesion needs validation; smoothness does not ensure bonding.|測剝離並定位實際破壞界面。~Measure peel and locate fracture interfaces.|表面越平滑金屬必黏得越牢~Assuming smoother glass always improves adhesion
種子覆蓋~Seed coverage|高深寬比孔壁的連續性決定後續鍍層。~High-aspect wall continuity determines subsequent plating.|檢查入口、中央和出口截面。~Inspect entrance, middle and exit sections.|雙面表面有種子即可證明孔壁相連~Inferring wall continuity from seeded faces
實心與鍍壁~Solid versus shell vias|實心和鍍壁導體的電、熱、機械行為不同。~Solid and shell conductors differ electrically, thermally and mechanically.|分別計算導電截面和金屬體積。~Calculate conducting area and metal volume separately.|鍍壁孔電阻可按實心孔算~Calculating shell-via resistance as a solid via
熱失配~Thermal mismatch|銅與玻璃膨脹差可集中孔邊應力。~Cu–glass expansion mismatch can concentrate rim stress.|比較溫度循環前後裂紋方位。~Compare crack orientation before/after cycling.|玻璃絕緣就表示沒有熱機風險~Equating insulation with no thermomechanical risk
高頻寄生~High-frequency parasitics|TGV 周圍回流結構決定電感和耦合。~Return structures around TGVs set inductance/coupling.|畫信號和地孔回路並建雙埠模型。~Draw signal/ground loops and two-port models.|低直流電阻即可保證高頻低損耗~Inferring low RF loss from low DC resistance
量測去嵌入~Measurement de-embedding|探針墊和走線會混入 TGV 的量測。~Probe pads/traces contaminate measured TGV behavior.|使用直通和開短路見證比較。~Compare thru/open/short witnesses.|量到的 S 參數全屬於孔洞本身~Assigning measured S-parameters entirely to vias
整合放行~Integration release|電連通、裂紋與玻璃處理良率須共同驗證。~Qualify continuity, cracks and handling yield together.|保存孔群位置和失效類型。~Retain array location and failure class.|只要 TGV 電阻低即可做大面積基板~Scaling substrates based only on low TGV resistance
''')
add(125,'矽中介層布線、TSV 與回流路徑~Silicon interposer routing, TSVs and return paths','接口與架構~Interfaces and architecture|高密度布線~Dense routing|垂直連通~Vertical connection|簽核與整合~Signoff and integration','imec3d intelpack', [('a129','高密度矽線路都用於晶粒間連接~Both use dense silicon routing between dies','中介層覆蓋較大面積，局部橋只服務相鄰晶粒邊界~Interposers cover larger areas; bridges serve local die shorelines'),('a134','回流、串擾及傳輸損耗分析可轉移~Return-path, crosstalk and loss analysis transfers','矽中介層還需處理基板耦合、TSV 和製造規則~Silicon interposers add substrate coupling, TSVs and process rules')], '假設可用邊長 10 mm、I/O 節距 50 μm、單列配置，理想最多 200 個位置；若每四位置需一個回流地，訊號位置上限約 150，還不含電源和保留區。~A 10 mm shoreline at 50 μm pitch permits an ideal 200 positions in one row. If one of every four is ground, signals are at most about 150 before power/keep-outs.', '''
被動與主動中介層~Passive and active interposers|是否含主動電路改變供電、測試和熱需求。~Active circuitry changes power, testing and thermal requirements.|標出被動線路及主動功能邊界。~Mark passive wiring and active functions.|所有矽中介層都只是無源連線~Treating all silicon interposers as passive
晶粒邊界分配~Die shoreline allocation|I/O 位置須同回流、電源與冗餘共享邊界。~I/O shares shoreline with returns, power and redundancy.|按實際節距計算可用連接數。~Count usable connections at actual pitch.|幾何位置數等於全部可用訊號數~Equating geometric positions with signal count
層疊規劃~Stackup planning|配線層與參考平面決定路由和阻抗。~Routing layers and reference planes determine routes/impedance.|畫每層介電厚度及回流。~Draw dielectric thickness and returns by layer.|增加金屬層總能無代價解決布線~Assuming extra metal layers solve routing without cost
線寬與損耗~Width and loss|細線降低擁塞但增加電阻，截面與金屬品質都重要。~Fine lines ease congestion but raise resistance; geometry and material matter.|比較兩種線寬的 RC 和面積。~Compare RC and area for two widths.|最細線寬總最節能~Assuming minimum width is always most energy-efficient
差分與回流~Differential and return paths|差分對仍需要定義共模回流和不平衡。~Differential pairs still need common-mode returns and imbalance control.|畫換層和地孔連接。~Draw transitions and ground-via connections.|差分訊號完全不需地參考~Assuming differential signals need no ground reference
彎折和過孔~Bends and vias|局部不連續會造成反射和模式轉換。~Local discontinuities cause reflections/mode conversion.|比較直線與過孔測試結構。~Compare straight and via test structures.|線長相同即傳輸行為相同~Equating length with transmission behavior
TSV 分配~TSV allocation|訊號、電源與地 TSV 的位置共同决定回路。~Signal, power and ground TSV locations jointly define loops.|建立 TSV 網路與電流密度圖。~Build TSV net and current-density maps.|地 TSV 可只按剩餘空間放置~Placing ground TSVs only in leftover space
矽基板耦合~Silicon substrate coupling|矽電阻率和偏壓影響損耗與串擾。~Silicon resistivity/bias affect loss and crosstalk.|比較基板模型與絕緣理想模型。~Compare substrate-aware and ideal-insulator models.|矽中介層可視為完全絕緣背景~Treating silicon as a perfect insulator
供電降壓~Power drop|高密度訊號布線不可侵占必要供電截面。~Dense signal routes must preserve power cross-section.|計算最遠節點 IR drop 和回路電感。~Calculate far-node IR drop and loop inductance.|信號 DRC 通過即可忽略供電能力~Ignoring power capacity after signal DRC passes
光罩與拼接~Reticle and stitching|大尺寸中介層可能需跨曝光場連線驗證。~Large interposers may require cross-field continuity checks.|在接縫放置電阻與套刻見證。~Put resistance/overlay witnesses at seams.|接縫只是圖面問題不影響電性~Treating seams as drawing-only issues
製造測試~Manufacturing test|短路、開路及寄生偏離需要不同測試結構。~Shorts, opens and parasitic deviations need different structures.|比較菊鍊、梳齒和 RF coupon。~Compare chains, combs and RF coupons.|導通測試即可覆蓋全部互連失效~Using continuity to cover every interconnect failure
共同簽核~Co-signoff|中介層、晶粒及封裝模型需相同端口與參考面。~Interposer, die and package models need consistent ports/reference planes.|檢查模型版本及重複計算界面。~Check versions and double-counted interfaces.|各自模擬合格可直接視為整機合格~Treating separate simulations as system qualification
''','a025')

def render_course(cid,d):
 base=CAT[cid]; z,en=base['title'],base['titleEn']; out={k:base[k] for k in ['id','title','titleEn','category']}
 src=['v9a-'+x for x in d['source']]
 out.update(kind='craft',status='guided',contentStatus='reviewable-educational-curriculum',curriculumVersion=9,depth=4,stepCount=24,estimatedMinutes=960,simulationOnly=True,languageCoverage=['zh-TW','en'],sourceIds=src,
 summary=f"以 12 個技術單元、24 步分析與驗證深入{d['focus'][0]}。逐一建立剖面、測試見證、失效判別和可審查的驗收證據。",
 summaryEn=f"Twelve technical units and 24 analysis/verification steps explore {d['focus'][1].lower()}, building sections, test witnesses, failure discrimination and reviewable acceptance evidence.",
 scope='公開工程原理與原創教學推理；數值是明示假設的算例，不是生產配方或供應商規格。各單元先建立物理模型，再設計能區分失效機制的量測。24 步是學習工作包，完整量產需經授權設備、材料及產品資格驗證。',
 scopeEn='Public engineering principles and original educational reasoning. Numbers are explicitly hypothetical examples, not production recipes or supplier specifications. Each unit builds a physical model then measurements that discriminate failure mechanisms. The 24 steps are learning work packages; production requires qualified equipment, materials and product validation.',
 diagram={'type':'packaging','labels':[s[0] for s in d['stages']],'labelsEn':[s[1] for s in d['stages']],'original':True,'notToScale':True}, stages=[])
 for si,(sz,se) in enumerate(d['stages']):
  stage={'id':f'{cid}-v9-stage{si+1:02d}','order':si+1,'title':sz,'titleEn':se,'description':f'針對{sz}完成三個專屬技術單元；每個單元包含物理分析與量測診斷兩步。','descriptionEn':f'Three dedicated units for {se.lower()}, each with physical analysis and measurement diagnosis.','steps':[]}
  for ui in range(si*3,si*3+3):
   (tz,te),(pz,pe),(mz,me),(fz,fe)=d['units'][ui]
   other=d['units'][(ui+5)%12][3]
   for mode in [0,1]:
    n=ui*2+mode+1; sid=f'{cid}-v9-{n:02d}'; phase=['機制與設計','證據與診斷'][mode]; phaseEn=['mechanism and design','evidence and diagnosis'][mode]
    correct=[pz,mz][mode];correctEn=[pe,me][mode]
    opts=[correct,fz,other[0]]; optsen=[correctEn,fe,other[1]]; shift=(n-1)%3;opts=opts[-shift:]+opts[:-shift] if shift else opts;optsen=optsen[-shift:]+optsen[:-shift] if shift else optsen
    instz=(f'本步先建立「{tz}」的模型：{pz} 在剖面或資料表中標出控制量、受影響量和交接介面；提出一組只改一項條件的比較，寫出預測方向。用「{mz}」規劃模型將如何被推翻；不要把畫得合理當作已經實測。' if mode==0 else f'以先前模型進行證據審查：{mz} 將「{fz}」當作待否定假說，另提出一項可能造成相同表象的混淆因素。安排對照樣本、座標和重複量測，分開記錄觀察值與機制推論；指出哪個結果會讓你暫停放行。')
    insten=(f'Build the model for {te.lower()}: {pe} Mark controlled quantities, responses and handoff interfaces in a section or data table. Compare two cases changing one condition and predict direction. Use this evidence plan: {me} State how the model could be falsified; a plausible drawing is not a measurement.' if mode==0 else f'Review the preceding model with evidence: {me} Challenge the hypothesis "{fe}" and name another mechanism that could give the same appearance. Plan controls, sampling coordinates and repeated measurements; separate observations from inference and identify a hold condition.')
    know=[{'id':sid+'-k1','title':tz+'：機制','titleEn':te+': mechanism','text':pz,'textEn':pe,'sourceIds':src},{'id':sid+'-k2','title':'量測與錯判分辨','titleEn':'Measurement and discrimination','text':mz+' 必須排除的錯判：'+fz+'。量測解析度、重複性與系統偏差分別列示；不同方法看到的範圍不可默認相同。','textEn':me+' Misinterpretation to reject: '+fe+'. Report resolution, repeatability and systematic bias separately; different methods do not automatically cover the same domain.','sourceIds':src}]
    if ui==8:
     instz+=' 原創算例：'+d['example'][0]+' 請重算一次，將一項輸入改變 10%，並指出此近似與本單元證據的關係。'
     insten+=' Original example: '+d['example'][1]+' Recalculate, vary one input by 10%, and relate the approximation to this unit’s evidence.'
     know.append({'id':sid+'-k3','title':'明示假設的量化算例','titleEn':'Quantitative example with explicit assumptions','text':d['example'][0],'textEn':d['example'][1]})
    step={'id':sid,'order':n,'sequence':n,'estimatedMinutes':40,'simulationOnly':True,'sourceIds':src,'prerequisiteIds':[f'{cid}-v9-{n-1:02d}'] if n>1 else [],'title':tz+'｜'+phase,'titleEn':te+' | '+phaseEn,'objective':f'針對{tz}，把「{pz}」轉成可驗證的工程判定，明確列出適用範圍與未知量。','objectiveEn':f'For {te.lower()}, turn "{pe}" into a testable engineering decision with explicit bounds and unknowns.','instruction':instz,'instructionEn':insten,'observation':mz+' 請分開列出符合預測與不符合預測的位置或樣本。','observationEn':me+' Report locations or samples agreeing and disagreeing with the prediction separately.','failure':'避免：'+fz+'。先檢查是否混用基準、忽略局部差異或超出模型範圍，再以本單元量測區分機制。','failureEn':'Avoid: '+fe+'. Check for mixed references, missed local variation or extrapolation before using this unit’s measurements to distinguish mechanisms.','check':(f'交付{tz}的剖面或因果圖、兩組條件比較及一項可否定預測的量測；標出單位、基準與前後站接口。' if mode==0 else f'交付{tz}的證據表：原始觀察、兩個競爭假說、對照方法、不確定度與接受／暫緩條件；至少一項證據須獨立於主要讀值。'),'checkEn':(f'Submit a section/causal diagram for {te.lower()}, a two-case comparison and one falsifying measurement; include units, datums and upstream/downstream interfaces.' if mode==0 else f'Submit evidence for {te.lower()}: observations, two competing hypotheses, controls, uncertainty and accept/hold criteria, including one observation independent of the main reading.'),'knowledge':know,'quiz':{'question':f'在「{tz}」的{phase}中，哪一項判斷或行動有充分依據？','questionEn':f'For {te.lower()} — {phaseEn} — which decision or action is justified?','options':opts,'optionsEn':optsen,'answer':shift,'explanation':pz+' '+mz+' 因此不能採用「'+fz+'」。','explanationEn':pe+' '+me+' Therefore reject: '+fe+'.'}}
    stage['steps'].append(step)
  out['stages'].append(stage)
 return out
# Early audit preview; final output is generated below after all authored units.
(ROOT/'tools/packaging-v9/sample_a.json').write_text(json.dumps(render_course('a103',D['a103']),ensure_ascii=False,indent=2)+'\n')

