SOURCES=[{'id':'v9a-'+i,'title':z,'titleEn':e,'publisher':p,'url':u,'scope':s,'scopeEn':se,'sourceType':'primary','category':'packaging','accessedAt':'2026-10-14','imageReuse':'link-only; no image reproduction permission inferred'} for i,z,e,p,u,s,se in SOURCE_ROWS]
SM={s['id']:s for s in SOURCES}
def ref(s):return {k:s[k] for k in ['title','titleEn','publisher','url']}
def make_place(cid,d):
 p=copy.deepcopy(PLACE[d['place']]);p['courseId']=cid
 p['summary']=CAT[cid]['title']+'的公開工程原理來自多家供應商與研究機構。地圖採用既有核對的代表據點：'+p['place']['name']+'，用來理解產業分工，不表示此課程全部工序於此執行，也不是唯一發明地。'
 p['summaryEn']='Public principles for '+CAT[cid]['titleEn'].lower()+' come from multiple suppliers and research institutions. This map reuses the verified reference '+p['place']['nameEn']+' to explain industrial roles; it does not locate every course operation or claim an exclusive invention site.'
 p['connection']='由'+d['focus'][0]+'延伸到相近課程，沿接口比較材料、幾何、量測與驗收，而不是直接複製設定。'
 p['connectionEn']='Follow '+d['focus'][1].lower()+' into related courses by comparing materials, geometry, measurement and acceptance at interfaces instead of copying settings.'
 p['references']=list({r['url']:r for r in p['references']+[ref(SM['v9a-'+s]) for s in d['source']]}.values())
 return p
related=[]
for cid,d in D.items():
 items=[]
 for k,(rid,t,di) in enumerate(d['related']):
  tz,te=t.split('~');dz,de=di.split('~');unit=d['units'][k*5]
  items.append({'id':rid,'title':CAT[rid]['title'],'titleEn':CAT[rid]['titleEn'],'why':tz,'whyEn':te,'transfer':tz,'transferEn':te,'difference':dz,'differenceEn':de,'practice':[f'以「{unit[0][0]}」畫出兩課的材料或資料交接，標明共同基準。',f'比較「{unit[1][0]}」在另一工法下還缺少哪項邊界條件。',f'用本課的「{unit[2][0]}」設計一項可轉移和一項不可直接轉移的驗收證據。'],'practiceEn':[f'Use {unit[0][1].lower()} to draw material/data handoffs and shared datums.',f'Identify missing boundary conditions when applying this mechanism to the other process: {unit[1][1]}',f'Using "{unit[2][1]}", define one transferable and one nontransferable acceptance item.'],'referenceUrls':[SM['v9a-'+s]['url'] for s in d['source']]})
 related.append({'courseId':cid,'overview':'依接口學習相近工法：'+d['focus'][0]+'。每個比較保留共同機制及不可直接轉移的邊界。','overviewEn':'Learn related methods through interfaces: '+d['focus'][1]+'. Each comparison retains both shared mechanisms and nontransferable boundaries.','related':items,'references':[ref(SM['v9a-'+s]) for s in d['source']]})
core={'courses':[render_course(cid,d) for cid,d in D.items()],'sources':SOURCES,'places':[make_place(cid,d) for cid,d in D.items()],'related':related}
assert len(core['courses'])==22
assert set(D)=={f'a{i}' for i in range(103,126)}-{'a106'}
assert all(len(c['stages'])==4 and all(len(s['steps'])==6 for s in c['stages']) for c in core['courses'])
assert all(s in SM for c in core['courses'] for s in c['sourceIds'])
(ROOT/'tools/packaging-v9/group_a_core.json').write_text(json.dumps(core,ensure_ascii=False,indent=2)+'\n')
(ROOT/'tools/packaging-v9/research_group_a.txt').write_text('V9 group A core primary-source research; accessed 2026-10-14.\nAuthoring scope: a103–a125 excluding a106 (22 courses).\nAll examples are original hypothetical calculations; source excerpts are paraphrased only as brief background. No supplier images reproduced.\n\n'+'\n'.join(f"{s['id']} | {s['publisher']} | {s['titleEn']}\n{s['url']}\n{s['scopeEn']}\n" for s in SOURCES))
print(json.dumps({'courses':len(core['courses']),'steps':sum(c['stepCount'] for c in core['courses']),'sources':len(SOURCES),'places':len(core['places']),'related':len(related)}))
